final ValueNotifier<bool> appUseLightTheme = ValueNotifier(false);

/// Globale Farben Hell/Dunkel (ThemeExtension) — greift in zentralen Widgets.
@immutable
class SolUi extends ThemeExtension<SolUi> {
  const SolUi({
    required this.scaffold,
    required this.card,
    required this.appBar,
    required this.onCard,
    required this.muted,
    required this.soft,
    required this.bottomNav,
    required this.navSelected,
    required this.navUnselected,
    required this.dailyCard,
    required this.dailyBorder,
  });

  final Color scaffold;
  final Color card;
  final Color appBar;
  final Color onCard;
  final Color muted;
  final Color soft;
  final Color bottomNav;
  final Color navSelected;
  final Color navUnselected;
  final Color dailyCard;
  final Color dailyBorder;

  // Kontrast 29.10.: Karten heben sich mehr vom Hintergrund ab,
  // Nebentexte besser lesbar. Vorher: scaffold 111111, card 1F1F1F,
  // muted B3FFFFFF, soft 8AFFFFFF, nav 7A7A7A (Branch backup-vor-kontrast-29-10).
  // Farben wie REPIT (29.10.): bg 0B0B0C, surface 151517, surface2 1D1D20,
  // fg F2EEE5, muted 8F8A7E, gold C9A24A. Vorheriger Stand: Branch backup-vor-kontrast-29-10.
  static const SolUi dark = SolUi(
    scaffold: Color(0xFF0B0B0C),
    card: Color(0xFF17171A),
    appBar: Color(0xFF0B0B0C),
    onCard: Color(0xFFF2EEE5),
    muted: Color(0xFFA39E92),
    soft: Color(0xFF8F8A7E),
    bottomNav: Color(0xFF0B0B0C),
    navSelected: Color(0xFFC9A24A),
    navUnselected: Color(0xFFA39E92),
    dailyCard: Color(0xFF1F1F22),
    dailyBorder: Color(0xFF2A2A2E),
  );


  static const SolUi light = SolUi(
    scaffold: Color(0xFFEDE8E0),
    card: Color(0xFFFFFBF7),
    appBar: Color(0xFFEDE8E0),
    onCard: Color(0xFF1E1A16),
    muted: Color(0xFF5C5750),
    soft: Color(0xFF6E6A63),
    bottomNav: Color(0xFFF5F0E8),
    navSelected: Color(0xFF7A5A1E),
    navUnselected: Color(0xFF7A756C),
    dailyCard: Color(0xFFF2EDE3),
    dailyBorder: Color(0x8EC9A24A),
  );

  @override
  SolUi copyWith({
    Color? scaffold,
    Color? card,
    Color? appBar,
    Color? onCard,
    Color? muted,
    Color? soft,
    Color? bottomNav,
    Color? navSelected,
    Color? navUnselected,
    Color? dailyCard,
    Color? dailyBorder,
  }) {
    return SolUi(
      scaffold: scaffold ?? this.scaffold,
      card: card ?? this.card,
      appBar: appBar ?? this.appBar,
      onCard: onCard ?? this.onCard,
      muted: muted ?? this.muted,
      soft: soft ?? this.soft,
      bottomNav: bottomNav ?? this.bottomNav,
      navSelected: navSelected ?? this.navSelected,
      navUnselected: navUnselected ?? this.navUnselected,
      dailyCard: dailyCard ?? this.dailyCard,
      dailyBorder: dailyBorder ?? this.dailyBorder,
    );
  }

  @override
  SolUi lerp(ThemeExtension<SolUi>? other, double t) {
    if (other is! SolUi) return this;
    return SolUi(
      scaffold: Color.lerp(scaffold, other.scaffold, t)!,
      card: Color.lerp(card, other.card, t)!,
      appBar: Color.lerp(appBar, other.appBar, t)!,
      onCard: Color.lerp(onCard, other.onCard, t)!,
      muted: Color.lerp(muted, other.muted, t)!,
      soft: Color.lerp(soft, other.soft, t)!,
      bottomNav: Color.lerp(bottomNav, other.bottomNav, t)!,
      navSelected: Color.lerp(navSelected, other.navSelected, t)!,
      navUnselected: Color.lerp(navUnselected, other.navUnselected, t)!,
      dailyCard: Color.lerp(dailyCard, other.dailyCard, t)!,
      dailyBorder: Color.lerp(dailyBorder, other.dailyBorder, t)!,
    );
  }
}

