  Widget _ringOverview({
    required double eaten,
    required double goal,
    required double protein,
    required double carbs,
    required double fat,
  }) {
    const gold = Color(0xFFC9A24A);
    const over = Color(0xFFA84A4A);
    final onCard = context.sol.onCard;
    final muted = context.sol.muted;
    final left = goal - eaten;
    // „Zu viel“ ab Ziel, ROT aber erst über der Obergrenze des Bereichs.
    final isOver = left < 0;
    final kRange = dailyKcalRange();
    final isOverRange = kRange.maxKcal > 0 && eaten > kRange.maxKcal;
    final inRange = eaten >= kRange.minKcal && !isOverRange;
    final ratio = goal > 0 ? (eaten / goal) : 0.0;
    final mg0 = effectiveMacroGoalsForDay(selectedDayKey);
    final mg = (
      protein: mg0.protein,
      carbs: mg0.carbs - _restCarbCutG(selectedDayKey),
      fat: mg0.fat,
    );

    Widget side(String value, String label) => Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              value,
              style: TextStyle(
                fontSize: 19,
                fontWeight: FontWeight.w800,
                color: onCard,
              ),
            ),
            const SizedBox(height: 2),
            Text(label, style: TextStyle(fontSize: 12.5, color: muted)),
          ],
        );

    Widget macro(String label, String key, double cur, double target, Color color) {
      final r = target > 0 ? (cur / target).clamp(0.0, 1.0) : 0.0;
      final mr = dailyMacroRange(key);
      final o = mr.maxG > 0 && cur > mr.maxG;
      final inR = cur >= mr.minG && !o;
      return Expanded(
        child: Padding(
          padding: const EdgeInsets.symmetric(horizontal: 6),
          child: Column(
            children: [
              Text(label,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: TextStyle(fontSize: 12.5, color: muted)),
              const SizedBox(height: 6),
              _barOutline(ClipRRect(
                borderRadius: BorderRadius.circular(4),
                child: LinearProgressIndicator(
                  value: r,
                  minHeight: 7,
                  backgroundColor: muted.withValues(alpha: 0.25),
                  valueColor: AlwaysStoppedAnimation<Color>(
                      o ? _barOver : (inR ? _barIn : _barUnder)),
                ),
              )),
              const SizedBox(height: 5),
              Text(
                "${cur.round()} / ${target.round()} g",
                style: TextStyle(
                  fontSize: 12.5,
                  fontWeight: FontWeight.w700,
                  color: onCard,
                ),
              ),
            ],
          ),
        ),
      );
    }

    return InkWell(
      borderRadius: BorderRadius.circular(12),
      onTap: () => setState(() => _macroDetailsExpanded = !_macroDetailsExpanded),
      child: Padding(
        padding: const EdgeInsets.fromLTRB(4, 10, 4, 8),
        child: Column(
          children: [
            Row(
              crossAxisAlignment: CrossAxisAlignment.center,
              children: [
                Expanded(
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Text(
                        _fmtThousands(left.abs()),
                        style: TextStyle(
                          fontSize: 19,
                          fontWeight: FontWeight.w800,
                          color: isOverRange ? over : onCard,
                        ),
                      ),
                      const SizedBox(height: 2),
                      Text(
                        isOver ? t("ring_over") : t("ring_left"),
                        style: TextStyle(
                          fontSize: 12.5,
                          color: isOverRange ? over : muted,
                        ),
                      ),
                      if (_plannedKcalForSelectedDay() > 0)
                        Padding(
                          padding: const EdgeInsets.only(top: 3),
                          child: Text(
                            () {
                              final r = left - _plannedKcalForSelectedDay();
                              return r >= 0
                                  ? tFmt("plan_rest", {"kcal": _fmtThousands(r)})
                                  : tFmt("plan_rest_over", {"kcal": _fmtThousands(-r)});
                            }(),
                            textAlign: TextAlign.center,
                            style: const TextStyle(
                              fontSize: 11,
                              color: gold,
                              fontWeight: FontWeight.w600,
                            ),
                          ),
                        ),
                    ],
                  ),
                ),
                SizedBox(
                  width: 150,
                  height: 124, // unten ist der Ring offen → weniger Leerraum
                  child: CustomPaint(
                    painter: _KcalRingPainter(
                      outline: Theme.of(context).brightness == Brightness.light
                          ? Colors.black.withValues(alpha: 0.22)
                          : null,
                      ratio: ratio,
                      track: muted.withValues(alpha: 0.22),
                      color: isOverRange ? _barOver : (inRange ? _barIn : _barUnder),
                    ),
                    child: Align(
                      alignment: const Alignment(0, 0.05),
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Text(
                            _fmtThousands(eaten),
                            style: TextStyle(
                              fontSize: 30,
                              fontWeight: FontWeight.w900,
                              color: onCard,
                              height: 1.0,
                            ),
                          ),
                          const SizedBox(height: 4),
                          Text(
                            t("ring_eaten"),
                            style: TextStyle(fontSize: 13, color: muted),
                          ),
                        ],
                      ),
                    ),
                  ),
                ),
                Expanded(child: side(_fmtThousands(goal), t("ring_goal"))),
              ],
            ),
            const SizedBox(height: 10),
            Row(
              children: [
                macro(t("carbs"), "carbs", carbs, mg.carbs, gold),
                macro(t("protein"), "protein", protein, mg.protein, gold),
                macro(t("fat"), "fat", fat, mg.fat, gold),
              ],
            ),
            // Aufgeklappt: kcal-Bereich des Tages.
            if (_macroDetailsExpanded && kRange.maxKcal > 0)
              Padding(
                padding: const EdgeInsets.only(top: 10),
                child: Text(
                  tFmt("ring_range", {
                    "a": _fmtThousands(kRange.minKcal),
                    "b": _fmtThousands(kRange.maxKcal),
                  }),
                  textAlign: TextAlign.center,
                  style: TextStyle(fontSize: 12.5, color: muted),
                ),
              ),
            if (_macroDetailsExpanded && _workoutTrackedToday) _dayFillButtons(),
          ],
        ),
      ),
    );
  }

  /// Hell-Modus: ganz leichte dunkle Umrandung um Balken (besser erkennbar).
  Widget _barOutline(Widget bar, {double radius = 8}) {
    if (Theme.of(context).brightness != Brightness.light) return bar;
    return Container(
      foregroundDecoration: BoxDecoration(
        borderRadius: BorderRadius.circular(radius),
        border: Border.all(
          color: Colors.black.withValues(alpha: 0.28),
          width: 0.8,
        ),
      ),
      child: bar,
    );
  }

