  Future<Food?> _pickFoodBySearch() async {
    var q = "";
    return showDialog<Food>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setL) {
          String norm(String x) => x
              .toLowerCase()
              .replaceAll("ä", "a")
              .replaceAll("ö", "o")
              .replaceAll("ü", "u")
              .replaceAll("ß", "ss");
          final words = norm(q).split(RegExp(r"\s+")).where((w) => w.isNotEmpty).toList();
          final hits = words.isEmpty
              ? <Food>[]
              : foodDatabase.where((f) => words.every(norm(f.name).contains)).take(12).toList();
          return AlertDialog(
            title: Text(t("meal_tpl_add_food")),
            content: SizedBox(
              width: 340,
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  TextField(
                    autofocus: true,
                    decoration: InputDecoration(
                      prefixIcon: const Icon(Icons.search, size: 20),
                      hintText: t("track_search_hint"),
                      isDense: true,
                    ),
                    onChanged: (v) => setL(() => q = v),
                  ),
                  const SizedBox(height: 8),
                  ConstrainedBox(
                    constraints: const BoxConstraints(maxHeight: 320),
                    child: ListView(
                      shrinkWrap: true,
                      children: [
                        for (final f in hits)
                          ListTile(
                            dense: true,
                            contentPadding: EdgeInsets.zero,
                            title: Text(f.name),
                            subtitle: Text(f.isRecipe
                                ? t("meal_tpl_recipe_fixed")
                                : "${f.calories.round()} kcal / 100 g"),
                            onTap: () => Navigator.pop(ctx, f),
                          ),
                      ],
                    ),
                  ),
                ],
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(ctx),
                child: Text(t("cancel")),
              ),
            ],
          );
        },
      ),
    );
  }

  Future<void> _editMealTemplate(Map<String, dynamic>? existing) async {
    final nameCtrl = TextEditingController(text: existing?["name"]?.toString() ?? "");
    final items = <String>[
      ...((existing?["items"] as List?) ?? const []).map((e) => e.toString())
    ];
    final res = await showDialog<String>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setL) => AlertDialog(
          title: Text(existing == null ? t("meal_tpl_new") : t("meal_tpl_edit")),
          content: SizedBox(
            width: 340,
            child: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  TextField(
                    controller: nameCtrl,
                    textCapitalization: TextCapitalization.sentences,
                    decoration: InputDecoration(labelText: t("meal_tpl_name")),
                  ),
                  const SizedBox(height: 14),
                  for (var i = 0; i < items.length; i++)
                    Row(
                      children: [
                        Icon(
                          (_foodByName(items[i])?.isRecipe ?? false)
                              ? Icons.lock_outline
                              : Icons.tune,
                          size: 18,
                          color: const Color(0xFFC9A24A),
                        ),
                        const SizedBox(width: 8),
                        Expanded(
                          child: Text(
                            (_foodByName(items[i])?.isRecipe ?? false)
                                ? "${items[i]} · ${t("meal_tpl_recipe_fixed")}"
                                : items[i],
                            style: const TextStyle(fontSize: 14),
                          ),
                        ),
                        IconButton(
                          icon: const Icon(Icons.close, size: 18),
                          onPressed: () => setL(() => items.removeAt(i)),
                        ),
                      ],
                    ),
                  TextButton.icon(
                    icon: const Icon(Icons.add),
                    label: Text(t("meal_tpl_add_food")),
                    onPressed: () async {
                      final f = await _pickFoodBySearch();
                      if (f != null && !items.contains(f.name)) {
                        setL(() => items.add(f.name));
                      }
                    },
                  ),
                ],
              ),
            ),
          ),
          actions: [
            if (existing != null)
              TextButton(
                onPressed: () => Navigator.pop(ctx, "delete"),
                child: Text(t("plan_remove"),
                    style: const TextStyle(color: Color(0xFFE57373))),
              ),
            TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: Text(t("cancel")),
            ),
            FilledButton(
              onPressed: () => Navigator.pop(ctx, "save"),
              child: Text(t("save")),
            ),
          ],
        ),
      ),
    );
    if (!mounted || res == null) return;
    setState(() {
      if (res == "delete" && existing != null) {
        userMealTemplates.remove(existing);
      } else if (res == "save" && items.isNotEmpty) {
        final name = nameCtrl.text.trim().isEmpty ? items.join(" + ") : nameCtrl.text.trim();
        if (existing != null) {
          existing["name"] = name;
          existing["items"] = items;
        } else {
          userMealTemplates.add({
            "id": "u${DateTime.now().millisecondsSinceEpoch}",
            "name": name,
            "items": items,
          });
        }
      }
    });
    _saveMealTemplates();
  }

  Future<void> _applyMealTemplate(String meal, Map<String, dynamic> tpl) async {
    final foods = <Food>[];
    for (final n in (tpl["items"] as List)) {
      final f = _foodByName(n.toString());
      if (f != null) foods.add(f);
    }
    if (foods.isEmpty) return;
    final solved = _solveMealTemplate(meal, foods);
    final ctrls = [
      for (final g in solved) TextEditingController(text: g.round().toString())
    ];
    final macros = ["protein", "carbs", "fat"];
    final targets = [
      for (final m in macros)
        () {
          final r = dynamicMealMacroRangeG(meal, m);
          return (r.minG + r.maxG) / 2.0 - (_mealTotals[meal]?[m] ?? 0.0);
        }()
    ];
    if (!mounted) return;
    final res = await showDialog<String>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setL) {
          double gOf(int i) =>
              double.tryParse(ctrls[i].text.replaceAll(",", ".")) ?? 0;
          double sum(double Function(Food) m) {
            var s = 0.0;
            for (var i = 0; i < foods.length; i++) {
              s += m(foods[i]) * gOf(i) / 100.0;
            }
            return s;
          }
          final p = sum((f) => f.protein), c = sum((f) => f.carbs), fa = sum((f) => f.fat);
          final kc = sum((f) => f.calories);
          Widget macroLine(String label, double v, double target) => Padding(
                padding: const EdgeInsets.symmetric(vertical: 2),
                child: Row(
                  children: [
                    Expanded(child: Text(label, style: const TextStyle(fontSize: 13))),
                    Text("${v.round()} ",
                        style: const TextStyle(fontWeight: FontWeight.w700, fontSize: 13)),
                    Text("/ ${math.max(0, target).round()} g",
                        style: const TextStyle(color: Color(0xFFC9A24A), fontSize: 12.5)),
                  ],
                ),
              );
          return AlertDialog(
            title: Text(tpl["name"].toString()),
            content: SizedBox(
              width: 340,
              child: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Text(t("meal_tpl_apply_hint"),
                        style: const TextStyle(fontSize: 12, color: Colors.white60, height: 1.35)),
                    const SizedBox(height: 12),
                    for (var i = 0; i < foods.length; i++)
                      Padding(
                        padding: const EdgeInsets.only(bottom: 10),
                        child: Row(
                          children: [
                            Icon(foods[i].isRecipe ? Icons.lock_outline : Icons.tune,
                                size: 18, color: const Color(0xFFC9A24A)),
                            const SizedBox(width: 8),
                            Expanded(child: Text(foods[i].name, style: const TextStyle(fontSize: 14))),
                            SizedBox(
                              width: 78,
                              child: TextField(
                                controller: ctrls[i],
                                enabled: !foods[i].isRecipe,
                                keyboardType: TextInputType.number,
                                textAlign: TextAlign.right,
                                decoration: const InputDecoration(isDense: true, suffixText: "g"),
                                onChanged: (_) => setL(() {}),
                              ),
                            ),
                          ],
                        ),
                      ),
                    const Divider(height: 18),
                    Text(t("meal_tpl_result"),
                        style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w700)),
                    const SizedBox(height: 4),
                    macroLine(t("protein"), p, targets[0]),
                    macroLine(t("carbs"), c, targets[1]),
                    macroLine(t("fat"), fa, targets[2]),
                    const SizedBox(height: 4),
                    Text("= ${kc.round()} kcal",
                        style: const TextStyle(fontWeight: FontWeight.w700)),
                  ],
                ),
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(ctx),
                child: Text(t("cancel")),
              ),
              TextButton(
                onPressed: () => Navigator.pop(ctx, "plan"),
                child: Text(t("plan_add_button")),
              ),
              FilledButton(
                onPressed: () => Navigator.pop(ctx, "add"),
                child: Text(t("add")),
              ),
            ],
          );
        },
      ),
    );
    if (!mounted || res == null) return;
    final grams = [
      for (final c in ctrls) double.tryParse(c.text.replaceAll(",", ".")) ?? 0
    ];
    setState(() {
      for (var i = 0; i < foods.length; i++) {
        if (grams[i] <= 0) continue;
        final e = TrackedFood(
          food: foods[i],
          grams: grams[i],
          meal: meal,
          dayKey: selectedDayKey,
        );
        (res == "plan" ? plannedFoods : trackedFoods).add(e);
      }
    });
    if (res == "plan") {
      _savePlannedFoods();
    } else {
      _updateMealTotals();
      _saveAppState();
      _showBlessing();
      _applyDailyKcalOverSchedule();
    }
  }

  // ───────────── Gewicht: Karte wie REPIT (Schnitt 7 Tage, Vorwoche, Verlauf) ─────────────
  final TextEditingController _weightTodayCtrl = TextEditingController();
  String? _weightTodayPrefilledFor;

  // Manuell eingetragene Wochenschnitte (falls woanders berechnet): [{at, kg}]
  static const String _kWeekAvgKey = "weight_week_avg_v1";
  List<Map<String, dynamic>> weekAvgEntries = [];

  Future<void> _loadWeekAvgEntries() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString(_kWeekAvgKey);
      if (raw == null || raw.isEmpty) return;
      final l = (jsonDecode(raw) as List)
          .map((e) => Map<String, dynamic>.from(e as Map))
          .toList();
      if (mounted) setState(() => weekAvgEntries = l);
    } catch (_) {}
  }

  Future<void> _saveWeekAvgEntries() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(_kWeekAvgKey, jsonEncode(weekAvgEntries));
    } catch (_) {}
  }

  double? _avgWeight(DateTime from, DateTime to) {
    // Manueller Wochenschnitt in diesem Zeitraum hat Vorrang (neuester zählt).
    Map<String, dynamic>? manual;
    for (final e in weekAvgEntries) {
      try {
        final d = dateFromKey(e["at"].toString());
        if (!d.isBefore(from) && !d.isAfter(to)) {
          if (manual == null || e["at"].toString().compareTo(manual["at"].toString()) > 0) {
            manual = e;
          }
        }
      } catch (_) {}
    }
    if (manual != null) return (manual["kg"] as num).toDouble();
    final vals = <double>[];
    weightHistory.forEach((k, v) {
      try {
        final d = dateFromKey(k);
        if (!d.isBefore(from) && !d.isAfter(to)) vals.add(v.kg);
      } catch (_) {}
    });
    if (vals.isEmpty) return null;
    return vals.reduce((a, b) => a + b) / vals.length;
  }

  Future<void> _saveWeightToday() async {
    final w = double.tryParse(_weightTodayCtrl.text.trim().replaceAll(",", "."));
    if (w == null || w < 25 || w > 400) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(t("track_error_bad"))),
      );
      return;
    }
    final key = dateKeyFromDate(_dateOnlyLocal(DateTime.now()));
    final old = weightHistory[key];
    setState(() {
      weightHistory[key] = _WeightDayEntry(
        kg: w,
        recordedAt: DateTime.now(),
        formImagePath: old?.formImagePath,
        formImageB64: old?.formImageB64,
      );
      currentWeightKg = w;
      if (nutritionMode != "Advanced") _applyAutoNutritionTargets();
    });
    await _saveAppState();
    _maybeWeeklyGoalRecalc();
    if (!mounted) return;
    FocusScope.of(context).unfocus();
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(t("weight_saved"))),
    );
  }

  Future<void> _enterWeekAverage({VoidCallback? onChanged}) async {
    final ctrl = TextEditingController();
    final v = await showDialog<String>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text(t("weight_week_avg_title")),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Text(t("weight_week_avg_hint"),
                style: const TextStyle(fontSize: 12.5, color: Colors.white60, height: 1.35)),
            const SizedBox(height: 12),
            TextField(
              controller: ctrl,
              autofocus: true,
              keyboardType: const TextInputType.numberWithOptions(decimal: true),
              decoration: const InputDecoration(suffixText: "kg"),
            ),
          ],
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx), child: Text(t("cancel"))),
          FilledButton(onPressed: () => Navigator.pop(ctx, ctrl.text), child: Text(t("save"))),
        ],
      ),
    );
    final w = double.tryParse((v ?? "").trim().replaceAll(",", "."));
    if (w == null || w < 25 || w > 400 || !mounted) return;
    final key = dateKeyFromDate(_dateOnlyLocal(DateTime.now()));
    setState(() {
      weekAvgEntries.removeWhere((e) => e["at"] == key);
      weekAvgEntries.add({"at": key, "kg": w});
      currentWeightKg = w;
      if (nutritionMode != "Advanced") _applyAutoNutritionTargets();
    });
    await _saveWeekAvgEntries();
    await _saveAppState();
    _maybeWeeklyGoalRecalc();
    onChanged?.call();
  }

