  List<(String, double)> _portionsFor(Food f) {
    final out = <(String, double)>[];
    if (f.isRecipe && f.basePortionGrams != null) {
      final b = f.basePortionGrams!;
      out.addAll([("½ Portion", b / 2), ("1 Portion", b), ("2 Portionen", b * 2)]);
    }
    out.addAll(_kPortionPresets[f.name] ?? const []);
    return out;
  }

  /// Standardmenge für die Liste: 1 Portion / mittlere Größe / 100 g.
  (String, double) _defaultPortion(Food f) {
    final p = _portionsFor(f);
    if (p.isEmpty) return ("100 g", 100);
    final one = p.where((e) => e.$1 == "1 Portion" || e.$1 == "Mittel" || e.$1 == "Ei M");
    return one.isNotEmpty ? one.first : p.first;
  }

  String _pickerType = "food"; // food | meals | recipes
  String _pickerCat = "Alle";
  String _pickerMode = "Alle"; // Alle | Diät | Aufbau
  String _pickerSort = "freq"; // freq | az | kcalUp | kcalDown | macroDown
  bool _pickerPer100 = true; // false = Portion/Menge, true = pro 100 g

  Map<String, int> _foodUsageCounts() {
    final m = <String, int>{};
    for (final t in trackedFoods) {
      m[t.food.name] = (m[t.food.name] ?? 0) + 1;
    }
    return m;
  }

  /// Dichte-Wert für Diät/Aufbau-Sortierung: Makro der Kategorie pro 100 g,
  /// sonst kcal pro 100 g.
  double _densityFor(Food f, String cat) => switch (cat) {
        "Carbs" => f.carbs,
        "Protein" => f.protein,
        "Fett" => f.fat,
        "Ballaststoffe" => f.fiber,
        _ => f.calories,
      };

  /// Diät: geringste Dichte oben · Aufbau: höchste Dichte oben.
  int _densityCompare(Food a, Food b, String cat, String mode) {
    final c = _densityFor(a, cat).compareTo(_densityFor(b, cat));
    if (c != 0) return mode == "Aufbau" ? -c : c;
    return a.name.toLowerCase().compareTo(b.name.toLowerCase());
  }

  Future<void> _openFoodPicker(String meal, {String? fillTag}) async {
    _pickerPer100 = true; // beim Öffnen immer pro 100 g
    var q = "";
    final usage = _foodUsageCounts();
    String norm(String x) => x
        .toLowerCase()
        .replaceAll("ä", "a")
        .replaceAll("ö", "o")
        .replaceAll("ü", "u")
        .replaceAll("ß", "ss");
    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      backgroundColor: context.sol.scaffold,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setL) {
          const gold = Color(0xFFC9A24A);
          final muted = context.sol.muted;
          final words = norm(q).split(RegExp(r"\s+")).where((w) => w.isNotEmpty).toList();
          bool match(String name) => words.every(norm(name).contains);

          List<Widget> rows;
          if (_pickerType == "meals") {
            final tpls = [...userMealTemplates, ..._solMealTemplates]
                .where((t) => match(t["name"].toString()))
                .toList();
            rows = [
              for (final tpl in tpls)
                _pickerRow(
                  title: tpl["name"].toString(),
                  sub: (tpl["items"] as List).join(" + "),
                  trailing: "",
                  onTap: () {
                    Navigator.pop(ctx);
                    _applyMealTemplate(meal, tpl);
                  },
                ),
              Padding(
                padding: const EdgeInsets.all(12),
                child: OutlinedButton.icon(
                  icon: const Icon(Icons.add),
                  label: Text(t("meal_tpl_new")),
                  onPressed: () async {
                    await _editMealTemplate(null);
                    setL(() {});
                  },
                ),
              ),
            ];
          } else {
            // Komplexe/einfache KH füllen → nur passende KH-Quellen.
            final kindOnly = fillTag == "cP"
                ? "komplex"
                : (fillTag == "cE" ? "einfach" : null);
            var list = foodDatabase.where((f) {
              if (_pickerType == "recipes" ? !f.isRecipe : f.isRecipe) return false;
              if (_pickerCat != "Alle" && !f.isInCategory(_pickerCat)) return false;
              if (kindOnly != null && f.carbKind != kindOnly) return false;
              return words.isEmpty || match(f.name);
            }).toList();
            // Makro passend zur Kategorie (für Anzeige + Sortierung).
            final macroKey = switch (_pickerCat) {
              "Carbs" => "c",
              "Protein" => "p",
              "Fett" => "f",
              "Ballaststoffe" => "fi",
              _ => "",
            };
            double macroOf(Food f) => switch (macroKey) {
                  "c" => f.carbs,
                  "p" => f.protein,
                  "f" => f.fat,
                  "fi" => f.fiber,
                  _ => 0,
                };
            int byName(Food a, Food b) =>
                a.name.toLowerCase().compareTo(b.name.toLowerCase());
            list.sort((a, b) {
              // Ohne Kategorie-Makro: „KH/P/F“-Sortierung = kcal.
              final sortKey = macroKey.isEmpty
                  ? (_pickerSort == "macroUp"
                      ? "kcalUp"
                      : (_pickerSort == "macroDown" ? "kcalDown" : _pickerSort))
                  : _pickerSort;
              switch (sortKey) {
                case "az":
                  return byName(a, b);
                case "kcalUp":
                  return a.calories.compareTo(b.calories);
                case "kcalDown":
                  return b.calories.compareTo(a.calories);
                case "macroDown":
                  final m = macroOf(b).compareTo(macroOf(a));
                  return m != 0 ? m : byName(a, b);
                case "macroUp":
                  final m2 = macroOf(a).compareTo(macroOf(b));
                  return m2 != 0 ? m2 : byName(a, b);
                default:
                  final u = (usage[b.name] ?? 0).compareTo(usage[a.name] ?? 0);
                  return u != 0 ? u : byName(a, b);
              }
            });
            final macroLabel = switch (macroKey) {
              "c" => t("abbr_carbs"),
              "p" => t("abbr_protein"),
              "f" => t("abbr_fat"),
              "fi" => t("picker_fiber_short"),
              _ => "",
            };
            rows = [
              for (final f in list)
                () {
                  final p0 = _defaultPortion(f);
                  final p = _pickerPer100 ? ("100 g", 100.0) : p0;
                  final fac = p.$2 / 100.0;
                  final mTxt = macroKey.isEmpty
                      ? ""
                      : " · $macroLabel ${(macroOf(f) * fac).round()} g";
                  return _pickerRow(
                    title: f.name,
                    sub: (p.$1 == "100 g" ? "100 g" : "${p.$1} (${p.$2.round()} g)") + mTxt,
                    trailing: "${(f.calories * fac).round()} kcal",
                    image: f.imagePath,
                    onTap: () async {
                      final added = await _openAmountDialog(f, meal, fillTag: fillTag);
                      if (added && ctx.mounted) Navigator.pop(ctx);
                    },
                  );
                }(),
            ];
          }

          Widget dd(String value, List<(String, String)> items, ValueChanged<String> on,
                  {bool enabled = true}) {
            final label = items.firstWhere((e) => e.$1 == value, orElse: () => items.first).$2;
            // Menü klappt immer NACH UNTEN auf (unter dem Feld).
