  /// Menge wählen (Portionen, Gramm, Füllen) → hinzufügen / vormerken. true = hinzugefügt.
  /// roh ↔ gekocht: passender Zwilling (z. B. „Reis (roh)“ ↔ „Reis (gekocht)“).
  Food? _cookedRawSibling(Food f) {
    final n = f.name;
    String? other;
    for (final (a, b) in const [
      ("(roh)", "(gekocht)"),
      (", roh)", ", gekocht)"),
      ("(gekocht)", "(roh)"),
      (", gekocht)", ", roh)"),
      (", gebraten)", ", roh)"),
    ]) {
      if (n.endsWith(a)) {
        other = n.substring(0, n.length - a.length) + b;
        break;
      }
    }
    if (other == null) return null;
    if (n.endsWith(", roh)") && _foodByName(other) == null) {
      other = "${n.substring(0, n.length - 6)}, gebraten)";
    }
    return _foodByName(other);
  }

  bool _isRawName(String n) => n.endsWith("(roh)") || n.endsWith(", roh)");

  Future<bool> _openAmountDialog(Food food, String meal, {String? fillTag}) async {
    final sibling = _cookedRawSibling(food);
    final portions = _portionsFor(food);
    final def = _defaultPortion(food);
    final ctrl = TextEditingController(text: def.$2.round().toString());
    double grams() => double.tryParse(ctrl.text.trim().replaceAll(",", ".")) ?? 0;
    String? fillMsg;
    // Kommt von einem „… füllen“-Knopf: Menge direkt bis zur Zielmitte setzen.
    if (fillTag != null) {
      final (String? mode, String? kind) = switch (fillTag) {
        "p" => ("protein", null),
        "c" => ("carbs", null),
        "f" => ("fat", null),
        "k" => ("kcal", null),
        "cP" => ("carbs", "komplex"),
        "cE" => ("carbs", "einfach"),
        _ => (null, null),
      };
      if (mode != null) {
        final g = _fillGramsForTarget(food, mode, meal,
            preWorkoutCarbKind: kind);
        if (g == null || g <= 0) {
          fillMsg = t("track_fill_none");
        } else {
          ctrl.text = g.round().toString();
        }
      }
    }
    final res = await showDialog<String>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setL) {
          void fill(String mode) {
            final g = _fillGramsForTarget(food, mode, meal);
            setL(() {
              if (g == null || g <= 0) {
                fillMsg = t("track_fill_none");
              } else {
                fillMsg = null;
                ctrl.text = g.round().toString();
              }
            });
          }

          return AlertDialog(
            title: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(food.name, style: const TextStyle(fontSize: 18)),
                if (sibling != null) ...[
                  const SizedBox(height: 8),
                  // Direkt umschalten: roh ↔ gekocht (Nährwerte passen sich an).
                  Row(
                    children: [
                      for (final raw in const [true, false])
                        Padding(
                          padding: const EdgeInsets.only(right: 6),
                          child: ChoiceChip(
                            visualDensity: VisualDensity.compact,
                            label: Text(raw ? t("raw_label") : t("cooked_label"),
                                style: const TextStyle(fontSize: 12.5)),
                            selected: _isRawName(food.name) == raw,
                            onSelected: (_) {
                              if (_isRawName(food.name) != raw) {
                                Navigator.pop(ctx, "swap");
                              }
                            },
                          ),
                        ),
                    ],
                  ),
                ],
              ],
            ),
            content: SizedBox(
              width: 360,
              child: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    if (portions.isNotEmpty) ...[
                      Wrap(
                        spacing: 6,
                        runSpacing: 4,
                        children: [
                          for (final p in portions)
                            ChoiceChip(
                              label: Text("${p.$1} · ${p.$2.round()} g",
                                  style: const TextStyle(fontSize: 12)),
                              selected: (grams() - p.$2).abs() < 0.5,
                              onSelected: (_) =>
                                  setL(() => ctrl.text = p.$2.round().toString()),
                            ),
                        ],
                      ),
                      const SizedBox(height: 10),
                    ],
                    TextField(
                      controller: ctrl,
                      keyboardType:
                          const TextInputType.numberWithOptions(decimal: true),
                      decoration: const InputDecoration(suffixText: "g"),
                      onChanged: (_) => setL(() {}),
                    ),
                    if (grams() > 0) _trackPortionMacroPreview(food, grams()),
                    const SizedBox(height: 8),
                    Wrap(
                      spacing: 4,
                      children: [
                        if (food.protein > 0.01)
                          ActionChip(
                              label: Text(t("track_fill_protein"),
                                  style: const TextStyle(fontSize: 11.5)),
                              onPressed: () => fill("protein")),
                        if (food.carbs > 0.01)
                          ActionChip(
                              label: Text(t("track_fill_carbs"),
                                  style: const TextStyle(fontSize: 11.5)),
                              onPressed: () => fill("carbs")),
                        if (food.fat > 0.01)
                          ActionChip(
                              label: Text(t("track_fill_fat"),
                                  style: const TextStyle(fontSize: 11.5)),
                              onPressed: () => fill("fat")),
                        ActionChip(
                            label: Text(t("track_fill_kcal"),
                                style: const TextStyle(fontSize: 11.5)),
                            onPressed: () => fill("kcal")),
                      ],
                    ),
                    if (fillMsg != null)
                      Text(fillMsg!,
                          style: const TextStyle(
                              fontSize: 12, color: Color(0xFFA84A4A))),
                  ],
                ),
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(ctx),
                child: Text(t("cancel")),
              ),
              TextButton(
                onPressed: grams() > 0 ? () => Navigator.pop(ctx, "plan") : null,
                child: Text(t("plan_add_button")),
              ),
              FilledButton(
                onPressed: grams() > 0 ? () => Navigator.pop(ctx, "add") : null,
                child: Text(t("add")),
              ),
            ],
          );
        },
      ),
    );
    final g = grams();
    if (res == "swap" && sibling != null && mounted) {
      return _openAmountDialog(sibling, meal, fillTag: fillTag);
    }
    if (!mounted || res == null || g <= 0) return false;
    final e = TrackedFood(food: food, grams: g, meal: meal, dayKey: selectedDayKey);
    if (res == "plan") {
      setState(() => plannedFoods.add(e));
      _savePlannedFoods();
      return true;
    }
    setState(() => trackedFoods.add(e));
    _updateMealTotals();
    _saveAppState();
    _showBlessing();
    _applyDailyKcalOverSchedule();
    return true;
  }

  // ───────────── Hilfetexte ein/aus ─────────────
  static const String _kShowHelpTextsKey = "show_help_texts_v1";
  bool showHelpTexts = true;

  Future<void> _loadHelpTextsPref() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final v = prefs.getBool(_kShowHelpTextsKey);
      if (v == null || !mounted) return;
      setState(() => showHelpTexts = v);
    } catch (_) {}
  }

  Future<void> _setHelpTexts(bool v) async {
    setState(() => showHelpTexts = v);
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setBool(_kShowHelpTextsKey, v);
    } catch (_) {}
  }

  // ───────────── Vorgeplante Mahlzeiten ─────────────
  // Eigene Liste, zählt NICHT ins Tracking. Abhaken = gegessen → wandert nach trackedFoods.
  static const String _kPlannedFoodsKey = "planned_foods_v1";
  List<TrackedFood> plannedFoods = [];

  Future<void> _loadPlannedFoods() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString(_kPlannedFoodsKey);
      if (raw == null || raw.isEmpty) return;
      final list = (jsonDecode(raw) as List)
          .map((e) => TrackedFood.fromMap(Map<String, dynamic>.from(e as Map)))
          .toList();
      if (!mounted) return;
      setState(() => plannedFoods = list);
    } catch (_) {}
  }

  Future<void> _savePlannedFoods() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(
        _kPlannedFoodsKey,
        jsonEncode(plannedFoods.map((p) => p.toMap()).toList()),
      );
    } catch (_) {}
  }

  List<TrackedFood> _plannedFor(String meal) => plannedFoods
      .where((p) => p.meal == meal && p.dayKey == selectedDayKey)
      .toList();

  void _confirmPlanned(TrackedFood p) {
    setState(() {
      plannedFoods.remove(p);
      trackedFoods.add(TrackedFood(
        food: p.food,
        grams: p.grams,
        meal: p.meal,
        dayKey: p.dayKey,
      ));
    });
    _updateMealTotals();
    _saveAppState();
    _savePlannedFoods();
    _showBlessing();
    _applyDailyKcalOverSchedule();
  }

  Future<void> _openPlannedEdit(TrackedFood p) async {
    final ctrl = TextEditingController(text: p.grams.round().toString());
    double grams() =>
        double.tryParse(ctrl.text.trim().replaceAll(",", ".")) ?? 0;
    final res = await showDialog<String>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setL) => AlertDialog(
          backgroundColor: const Color(0xFF1E1E1E),
          title: Text(p.food.name, style: const TextStyle(fontSize: 18)),
          content: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Text(
                  t("plan_edit_hint"),
                  style: const TextStyle(
                      fontSize: 12.5, color: Colors.white60, height: 1.3),
                ),
                const SizedBox(height: 10),
                TextField(
                  controller: ctrl,
                  keyboardType:
                      const TextInputType.numberWithOptions(decimal: true),
                  decoration: InputDecoration(
                    labelText: t("plan_amount_label"),
                    suffixText: "g",
                  ),
                  onChanged: (_) => setL(() {}),
                ),
                if (grams() > 0) _trackPortionMacroPreview(p.food, grams()),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(ctx, "delete"),
              child: Text(
                t("plan_remove"),
                style: const TextStyle(color: Color(0xFFE57373)),
              ),
            ),
            TextButton(
              onPressed: grams() > 0 ? () => Navigator.pop(ctx, "save") : null,
              child: Text(t("save")),
            ),
            FilledButton(
              onPressed: grams() > 0 ? () => Navigator.pop(ctx, "eaten") : null,
              child: Text(t("plan_eaten_button")),
            ),
          ],
        ),
      ),
    );
    final g = grams();
    if (!mounted || res == null) return;
    if (res == "delete") {
      setState(() => plannedFoods.remove(p));
      _savePlannedFoods();
      return;
    }
    if (g <= 0) return;
    setState(() => p.grams = g);
    if (res == "eaten") {
      _confirmPlanned(p);
    } else {
      _savePlannedFoods();
    }
  }

  /// In der Mahlzeit-Karte: geplante Einträge ausgegraut mit Haken-Kästchen.
  Widget _plannedFoodsBlock(String meal, {bool workoutBlock = false}) {
    final items = workoutBlock
        ? [..._plannedFor("Pre-Workout"), ..._plannedFor("Post-Workout")]
        : _plannedFor(meal);
    if (items.isEmpty) return const SizedBox.shrink();
    final muted = context.sol.muted;
    final kc = items.fold(0.0, (a, p) => a + p.calories);
    // Zweiter Balken „Mit Plan“: gegessen + alles Geplante gegen die Zielmitte.
    final double eaten;
    final double minK;
    final double maxK;
    if (workoutBlock) {
      eaten = _workoutBlockAggregatedTotals()['calories'] ?? 0.0;
      final r = _workoutBlockKcalRange();
      minK = r.minKcal;
      maxK = r.maxKcal;
    } else {
      eaten = _mealTotals[meal]?['calories'] ?? 0.0;
      final r = displayMealKcalRangeForUi(meal);
      minK = r.minKcal;
      maxK = r.maxKcal;
    }
    final mid = (_mealCenterKcal(workoutBlock ? _kWorkoutBlockMealId : meal) ??
            (minK + maxK) / 2.0)
        .clamp(minK, math.max(minK, maxK))
        .toDouble();
    final withPlan = eaten + kc;
    final scaleEnd = math.max(maxK * 1.1, withPlan);
    final ratio = scaleEnd > 0 ? (withPlan / scaleEnd).clamp(0.0, 1.0) : 0.0;
    final midRatio = scaleEnd > 0 ? (mid / scaleEnd).clamp(0.0, 1.0) : 0.0;
    // Alles grau: nur Vorschau, nicht mit dem echten Balken verwechseln.
    final grey = muted.withValues(alpha: 0.75);
    final barColor = muted.withValues(alpha: 0.45);
    return Padding(
      padding: const EdgeInsets.only(top: 8),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 6),
            child: Row(
              children: [
                Text(
                  t("plan_with_plan"),
                  style: TextStyle(
                    fontSize: 11,
                    fontWeight: FontWeight.w600,
                    color: grey,
                  ),
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: _barOutline(
                    Stack(
                      children: [
                        ClipRRect(
                          borderRadius: BorderRadius.circular(6),
                          child: LinearProgressIndicator(
                            value: ratio,
                            minHeight: 8,
                            color: barColor,
                            backgroundColor: muted.withValues(alpha: 0.12),
                          ),
                        ),
                        Positioned.fill(
                          child: LayoutBuilder(builder: (ctx, c) {
                            final w = c.maxWidth;
                            if (w <= 2) return const SizedBox.shrink();
                            return Stack(children: [
                              Positioned(
                                left: (w * midRatio - 1)
                                    .clamp(0.0, w - 2)
                                    .toDouble(),
                                top: 0,
                                bottom: 0,
                                child: Container(width: 2, color: grey),
                              ),
                            ]);
                          }),
                        ),
                      ],
                    ),
                    radius: 6,
                  ),
                ),
                const SizedBox(width: 10),
                Text.rich(
                  TextSpan(children: [
                    TextSpan(
                      text: withPlan.round().toString(),
                      style: TextStyle(
                        fontWeight: FontWeight.w700,
                        fontSize: 13,
                        color: grey,
                      ),
                    ),
                    TextSpan(
                      text: " / ",
                      style: TextStyle(fontSize: 12, color: muted),
                    ),
                    TextSpan(
                      text: mid.round().toString(),
                      style: TextStyle(
                        fontWeight: FontWeight.w600,
                        fontSize: 12.5,
                        color: grey,
                      ),
                    ),
                  ]),
                ),
              ],
            ),
          ),
          const SizedBox(height: 2),
          for (final p in items)
            Row(
              children: [
                IconButton(
                  padding: EdgeInsets.zero,
                  visualDensity: VisualDensity.compact,
                  constraints:
                      const BoxConstraints(minWidth: 36, minHeight: 34),
                  tooltip: t("plan_eaten_button"),
                  icon: Icon(Icons.check_box_outline_blank,
                      size: 22, color: muted),
                  onPressed: () => _confirmPlanned(p),
                ),
                Expanded(
                  child: InkWell(
                    onTap: () => _openPlannedEdit(p),
                    child: Padding(
                      padding: const EdgeInsets.symmetric(vertical: 6),
                      child: Text(
                        "${p.food.name} · ${p.grams.round()} g · ${p.calories.round()} kcal",
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: TextStyle(
                          fontSize: 12.5,
                          color: muted.withValues(alpha: 0.8),
                          fontStyle: FontStyle.italic,
                        ),
                      ),
                    ),
                  ),
                ),
              ],
            ),
        ],
      ),
    );
  }

  double _dayGoalKcalForOverview() {
    if (!isCheatDay(selectedDayKey)) {
      return goalCalories - _restCarbCutG(selectedDayKey) * 4.1;
    }
    if (isSelectedDayCrashout) return goalCalories;
    final eff = effectiveGoalKcalForDay(selectedDayKey);
    return eff > 0 ? eff : goalCalories;
  }

  double _plannedKcalForSelectedDay() => plannedFoods
      .where((p) => p.dayKey == selectedDayKey)
      .fold(0.0, (a, p) => a + p.calories);

  /// Tagesübersicht: „Wenn du alles isst: …“ (nur wenn etwas geplant ist).
  Widget _plannedDayPreview() {
    final items =
        plannedFoods.where((p) => p.dayKey == selectedDayKey).toList();
    if (items.isEmpty) return const SizedBox.shrink();
    final eaten =
        trackedFoods.where((f) => f.dayKey == selectedDayKey).toList();
    double sum(List<TrackedFood> l, double Function(TrackedFood) f) =>
        l.fold(0.0, (a, e) => a + f(e));
    final all = [...eaten, ...items];
    return Padding(
      padding: const EdgeInsets.only(top: 6, bottom: 2),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(8),
          border: Border.all(
              color: const Color(0xFFC9A24A).withValues(alpha: 0.35)),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              () {
                final tot = sum(all, (e) => e.calories);
                final rest = _dayGoalKcalForOverview() - tot;
                return "${tFmt("plan_day_preview", {"kcal": tot.round()})}  (${rest >= 0 ? tFmt("plan_rest", {"kcal": rest.round()}) : tFmt("plan_rest_over", {"kcal": (-rest).round()})})";
              }(),
              style: TextStyle(
                fontWeight: FontWeight.w700,
                fontSize: 13,
                color: context.sol.onCard,
              ),
            ),
            const SizedBox(height: 2),
            Text(
              "${t("abbr_protein")} ${sum(all, (e) => e.protein).round()} · ${t("abbr_carbs")} ${sum(all, (e) => e.carbs).round()} · ${t("abbr_fat")} ${sum(all, (e) => e.fat).round()} g  ·  ${tFmt("plan_day_open", {"kcal": sum(items, (e) => e.calories).round()})}",
              style: TextStyle(fontSize: 11.5, color: context.sol.muted),
            ),
          ],
        ),
      ),
    );
  }

  // ───────────── Phasen-Ziel (Countdown) ─────────────
  // Gespeichert als JSON: {kg, bulk, kcal, start}. 7000 kcal ≈ 1 kg.
  static const String _kPhaseGoalKey = "phase_goal_v1";
  Map<String, dynamic>? phaseGoal;

  Future<void> _loadPhaseGoal() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString(_kPhaseGoalKey);
      if (raw == null || raw.isEmpty) return;
      final m = Map<String, dynamic>.from(jsonDecode(raw) as Map);
      if (!mounted) return;
      setState(() => phaseGoal = m);
      // Gewichte werden parallel geladen — kurz warten, dann ggf. Wochen-Update.
      Future.delayed(const Duration(seconds: 3), () {
        if (mounted) _maybeWeeklyGoalRecalc();
      });
    } catch (_) {}
  }

  Future<void> _savePhaseGoal(Map<String, dynamic>? g) async {
    setState(() => phaseGoal = g);
    try {
      final prefs = await SharedPreferences.getInstance();
      if (g == null) {
        await prefs.remove(_kPhaseGoalKey);
      } else {
        await prefs.setString(_kPhaseGoalKey, jsonEncode(g));
      }
    } catch (_) {}
  }

  /// Vorschlag kcal/Tag aus dem aktuellen Plan (Bedarf ↔ Tagesziel).
  double _phaseGoalSuggestedDailyKcal() {
    final d = (_maintenanceKcalFromBody() - goalCalories).abs();
    if (d < 100) return 500;
    return (d / 10).round() * 10.0;
  }

  String _fmtThousands(num v) {
    final s = v.round().abs().toString();
    final b = StringBuffer(v < 0 ? "-" : "");
    for (var i = 0; i < s.length; i++) {
      if (i > 0 && (s.length - i) % 3 == 0) b.write("'");
      b.write(s[i]);
    }
    return b.toString();
  }

  String _fmtKgGoal(double kg) {
    final r = (kg * 10).round() / 10;
    return r == r.roundToDouble() ? r.toStringAsFixed(0) : r.toStringAsFixed(1);
  }

  /// Status: geschafft (aus getrackten, abgeschlossenen Tagen seit Start),
  /// Rest, verbleibende Tage und ungefähres Zieldatum.
  ({
    bool bulk,
    double kg,
    double totalKcal,
    double doneKcal,
    double dailyKcal,
    int daysLeft,
    DateTime eta,
    double progress,
  })? _phaseGoalStatus() {
    final g = phaseGoal;
    if (g == null) return null;
    final kg = ((g["kg"] ?? 0) as num).toDouble();
    final daily = ((g["kcal"] ?? 0) as num).toDouble();
    final bulk = g["bulk"] == true;
    if (kg <= 0 || daily <= 0) return null;
    final total = kg * 7000.0;
    final today = _dateOnlyLocal(DateTime.now());
    var start = today;
    try {
      start = _dateOnlyLocal(dateFromKey((g["start"] ?? "").toString()));
    } catch (_) {}
    // Intelligent: Fortschritt nach Wochenschnitt-Gewicht (einmal pro Woche aktualisiert).
    if (g["adjust"] == "smart" &&
        g["targetWeight"] is num &&
        g["startWeight"] is num) {
      final tw = (g["targetWeight"] as num).toDouble();
      // Start = Wochenschnitt bis zum Startdatum (gleiche Basis wie der
      // Wochen-Abgleich) — einzelne Tage schwanken zu stark (Wasser).
      final sw = _avgWeight(start.subtract(const Duration(days: 6)), start) ??
          (g["startWeight"] as num).toDouble();
      var snapValid = false;
      if (g["snapW"] is num && g["snapAt"] != null) {
        try {
          snapValid = dateFromKey(g["snapAt"].toString())
                  .difference(start)
                  .inDays >=
              7;
        } catch (_) {}
      }
      final nowW = snapValid ? (g["snapW"] as num).toDouble() : sw;
      final kgTotal = (tw - sw).abs();
      // Täglich: eingesparte kcal seit dem letzten Wochen-Abgleich dazurechnen.
      // Einmal pro Woche wird mit dem echten Wochenschnitt-Gewicht neu kalibriert.
      var since = start;
      if (snapValid) {
        try {
          since = _dateOnlyLocal(dateFromKey(g["snapAt"].toString()));
        } catch (_) {}
      }
      final maintS = _maintenanceKcalFromBody();
      var kcalSince = 0.0;
      var dS = since;
      var guardS = 0;
      while (dS.isBefore(today) && guardS < 400) {
        final key = dateKeyFromDate(dS);
        if (trackedFoods.any((t) => t.dayKey == key)) {
          final eat = _kcalEatenOnDay(key);
          kcalSince += bulk ? (eat - maintS) : (maintS - eat);
        }
        dS = dS.add(const Duration(days: 1));
        guardS++;
      }
      final estW = bulk ? nowW + kcalSince / 7000.0 : nowW - kcalSince / 7000.0;
      final remaining = math.max(0.0, bulk ? tw - estW : estW - tw);
      int daysLeft;
      if (g["targetDate"] != null) {
        try {
          daysLeft = math.max(0,
              dateFromKey(g["targetDate"].toString()).difference(today).inDays);
        } catch (_) {
          daysLeft = (remaining * 7000 / daily).ceil();
        }
      } else {
        daysLeft = remaining <= 0 ? 0 : (remaining * 7000 / daily).ceil();
      }
      if (remaining <= 0) daysLeft = 0;
      final doneKg = (kgTotal - remaining).clamp(0.0, kgTotal);
      return (
        bulk: bulk,
        kg: kgTotal,
        totalKcal: kgTotal * 7000,
        doneKcal: doneKg * 7000,
        dailyKcal: daily,
        daysLeft: daysLeft,
        eta: today.add(Duration(days: daysLeft)),
        progress: kgTotal > 0 ? (doneKg / kgTotal).clamp(0.0, 1.0) : 0.0,
      );
    }
    final maint = _maintenanceKcalFromBody();
    var done = 0.0;
    var day = start;
    var guard = 0;
    while (day.isBefore(today) && guard < 1000) {
      final key = dateKeyFromDate(day);
      if (trackedFoods.any((t) => t.dayKey == key)) {
        final eat = _kcalEatenOnDay(key);
        done += bulk ? (eat - maint) : (maint - eat);
      }
      day = day.add(const Duration(days: 1));
      guard++;
    }
    done = done.clamp(0.0, total);
    final rest = total - done;
    final daysLeft = rest <= 0 ? 0 : (rest / daily).ceil();
    return (
      bulk: bulk,
      kg: kg,
      totalKcal: total,
      doneKcal: done,
      dailyKcal: daily,
      daysLeft: daysLeft,
      eta: today.add(Duration(days: daysLeft)),
      progress: total > 0 ? (done / total).clamp(0.0, 1.0) : 0.0,
    );
  }

  String _phaseGoalEtaLabel(DateTime d) =>
      "${t("weekday_${d.weekday}")} ${d.day}.${d.month}.";

  /// Kompakte Karte auf dem Tracking-Screen (nur wenn ein Ziel gesetzt ist).
