    );
  }

  /// Verlauf (Gewicht seit Phasenstart, mind. 4 Wochen) + Plan-Linie bis Ziel.
  Widget _phaseGoalChart({required double target, DateTime? eta}) {
    const gold = Color(0xFFC9A24A);
    final muted = context.sol.muted;
    final today = _dateOnlyLocal(DateTime.now());
    var from = today.subtract(const Duration(days: 28));
    final st = phaseGoal?["start"];
    if (st != null) {
      try {
        final d = _dateOnlyLocal(dateFromKey(st.toString()));
        if (d.isBefore(from)) from = d;
      } catch (_) {}
    }
    final pts = <MapEntry<DateTime, double>>[];
    weightHistory.forEach((k, v) {
      try {
        final d = dateFromKey(k);
        if (!d.isBefore(from) && !d.isAfter(today)) pts.add(MapEntry(d, v.kg));
      } catch (_) {}
    });
    pts.sort((a, b) => a.key.compareTo(b.key));
    if (pts.isEmpty) return const SizedBox.shrink();
    final first = pts.first.key;
    double x(DateTime d) => d.difference(first).inDays.toDouble();
    final hist = [for (final p in pts) FlSpot(x(p.key), p.value)];
    final cur = currentWeightKg;
    final end = eta ?? today;
    final plan = [FlSpot(x(today), cur), FlSpot(x(end), target)];
    final ys = [...pts.map((e) => e.value), target, cur];
    final minY = (ys.reduce(math.min) - 1).floorToDouble();
    final maxY = (ys.reduce(math.max) + 1).ceilToDouble();
    final maxX = math.max(1.0, x(end));
    String dl(DateTime d) => "${d.day}.${d.month}.";
    return Container(
      padding: const EdgeInsets.fromLTRB(4, 10, 12, 4),
      decoration: BoxDecoration(
        color: Colors.white.withValues(alpha: 0.03),
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: muted.withValues(alpha: 0.25)),
      ),
      child: SizedBox(
        height: 150,
        child: LineChart(
          LineChartData(
            minX: 0,
            maxX: maxX,
            minY: minY,
            maxY: maxY,
            lineTouchData: const LineTouchData(enabled: false),
            borderData: FlBorderData(show: false),
            gridData: FlGridData(
              show: true,
              drawVerticalLine: false,
              horizontalInterval: ((maxY - minY) / 3).clamp(0.5, 100),
              getDrawingHorizontalLine: (_) =>
                  FlLine(color: muted.withValues(alpha: 0.15), strokeWidth: 1),
            ),
            titlesData: FlTitlesData(
              topTitles: const AxisTitles(sideTitles: SideTitles(showTitles: false)),
              rightTitles: const AxisTitles(sideTitles: SideTitles(showTitles: false)),
              leftTitles: AxisTitles(
                sideTitles: SideTitles(
                  showTitles: true,
                  reservedSize: 34,
                  interval: ((maxY - minY) / 3).clamp(0.5, 100),
                  getTitlesWidget: (v, m) => SideTitleWidget(
                    meta: m,
                    space: 4,
                    child: Text(v.toStringAsFixed(0),
                        style: TextStyle(color: muted, fontSize: 10)),
                  ),
                ),
              ),
              bottomTitles: AxisTitles(
                sideTitles: SideTitles(
                  showTitles: true,
                  reservedSize: 20,
                  interval: maxX,
                  getTitlesWidget: (v, m) => SideTitleWidget(
                    meta: m,
                    space: 4,
                    child: Text(dl(first.add(Duration(days: v.round()))),
                        style: TextStyle(color: muted, fontSize: 10)),
                  ),
                ),
              ),
            ),
            extraLinesData: ExtraLinesData(horizontalLines: [
              HorizontalLine(
                y: target,
                color: gold.withValues(alpha: 0.8),
                strokeWidth: 1.2,
                dashArray: const [6, 5],
                label: HorizontalLineLabel(
                  show: true,
                  alignment: Alignment.topLeft,
                  style: const TextStyle(
                      color: gold, fontSize: 10.5, fontWeight: FontWeight.w700),
                  labelResolver: (_) => "${t("ring_goal")} ${_fmtKgGoal(target)} kg",
                ),
              ),
            ]),
            lineBarsData: [
              // Plan: heute → Ziel (gestrichelt)
              LineChartBarData(
                spots: plan,
                color: muted.withValues(alpha: 0.8),
                barWidth: 1.6,
                dashArray: const [4, 4],
                dotData: FlDotData(
                  show: true,
                  checkToShowDot: (s, d) => s.x == plan.last.x,
                  getDotPainter: (s, p, d, i) => FlDotCirclePainter(
                      radius: 3, color: gold, strokeWidth: 0),
                ),
              ),
              // Verlauf (echte Messungen)
              LineChartBarData(
                spots: hist,
                color: gold,
                barWidth: 2.2,
                dotData: FlDotData(
                  show: true,
                  checkToShowDot: (s, d) => s.x == hist.last.x,
                  getDotPainter: (s, p, d, i) => FlDotCirclePainter(
                      radius: 3.5, color: gold, strokeWidth: 0),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Future<void> _openPhaseGoalDialog() async {
    final g = phaseGoal;
    final curW = currentWeightKg;
    final startTarget = g != null && g["targetWeight"] is num
        ? (g["targetWeight"] as num).toDouble()
        : (g != null
            ? curW +
                (((g["bulk"] == true) ? 1 : -1) *
                    ((g["kg"] ?? 0) as num).toDouble())
            : (nutritionMode == "Aufbau" ? curW + 2 : curW - 2));
    final targetCtrl = TextEditingController(text: _fmtKgGoal(startTarget));
    final kcalCtrl = TextEditingController(
      text: (g != null
              ? ((g["kcal"] ?? 0) as num).toDouble()
              : _phaseGoalSuggestedDailyKcal())
          .round()
          .toString(),
    );
    // Tempo: moderat / normal / aggressiv / plan / custom
    var tempo = (g?["tempo"] ?? "plan").toString();
    DateTime? targetDate;
    if (g?["targetDate"] != null) {
      try {
        targetDate = dateFromKey(g!["targetDate"].toString());
      } catch (_) {}
    }
    var advanced = tempo == "custom";
    var adjust = (g?["adjust"] ?? "smart").toString();
    double? parse(String v) =>
        double.tryParse(v.trim().replaceAll(",", ".").replaceAll("'", ""));
    const tempoKcal = {"moderat": 300.0, "normal": 500.0, "aggressiv": 800.0};
    final result = await showDialog<String>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setL) {
          final tw = parse(targetCtrl.text) ?? curW;
          final diff = tw - curW;
          final bulk = diff > 0;
          final kg = diff.abs();
          final today = _dateOnlyLocal(DateTime.now());
          double kc;
          if (advanced && targetDate != null) {
            final days = targetDate!.difference(today).inDays;
            kc = days > 0 ? kg * 7000 / days : 0;
          } else if (advanced) {
            kc = parse(kcalCtrl.text) ?? 0;
          } else if (tempo == "plan") {
            kc = _phaseGoalSuggestedDailyKcal();
          } else {
            kc = tempoKcal[tempo] ?? 500;
          }
          String preview = "";
          String warn = "";
          DateTime? etaForChart;
          if (kg >= 0.1 && kc > 0) {
            final total = kg * 7000;
            final days = (total / kc).ceil();
            final eta = today.add(Duration(days: days));
            etaForChart = eta;
            preview = tFmt("phase_goal_preview2", {
              "dir": bulk ? "+" : "−",
              "kg": _fmtKgGoal(kg),
              "total": _fmtThousands(total),
              "kcal": _fmtThousands(kc),
              "days": days,
              "date": "${_phaseGoalEtaLabel(eta)}${eta.year}",
            });
            if (bulk) {
              // Grobe Muskel-Schätzung: Fortgeschritten ~0,25, Anfänger ~0,9 kg/Monat.
              final months = days / 30.4;
              final lo = math.min(kg, 0.25 * months);
              final hi = math.min(kg, 0.9 * months);
              preview += "\n${tFmt("phase_goal_muscle", {
                "a": _fmtKg1(lo),
                "b": _fmtKg1(hi),
              })}";
            }
            if (!bulk && kc > 1000) warn = t("phase_goal_warn_fast");
            if (bulk && kc > 500) warn = t("phase_goal_warn_bulk");
          }
          Widget chip(String id, String label) => ChoiceChip(
                label: Text(label, style: const TextStyle(fontSize: 12.5)),
                selected: !advanced && tempo == id,
                onSelected: (_) => setL(() {
                  advanced = false;
                  tempo = id;
                }),
              );
          return AlertDialog(
            title: Text(t("phase_goal_title")),
            content: SizedBox(
              width: 360,
              child: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    TextField(
                      controller: targetCtrl,
                      keyboardType:
                          const TextInputType.numberWithOptions(decimal: true),
                      decoration: InputDecoration(
                        labelText: t("phase_goal_target_weight"),
                        suffixText: "kg",
                        helperText: tFmt("phase_goal_current", {
                          "w": _fmtKgGoal(curW),
                          "d": "${bulk ? "+" : "−"}${_fmtKgGoal(kg)}",
                        }),
                      ),
                      onChanged: (_) => setL(() {}),
                    ),
                    const SizedBox(height: 12),
                    // Kleiner Chart: bisheriger Verlauf + geplanter Weg zum Ziel.
                    _phaseGoalChart(target: tw, eta: etaForChart),
                    const SizedBox(height: 12),
                    Text(t("phase_goal_tempo"),
                        style: const TextStyle(
                            fontSize: 12,
                            fontWeight: FontWeight.w700,
                            color: Color(0xFFC9A24A))),
                    const SizedBox(height: 6),
                    Wrap(
                      spacing: 6,
                      runSpacing: 4,
                      children: [
                        chip("moderat", t("phase_tempo_moderat")),
                        chip("normal", t("phase_tempo_normal")),
                        chip("aggressiv", t("phase_tempo_aggressiv")),
                        chip("plan", tFmt("phase_tempo_plan", {
                          "kcal": _fmtThousands(_phaseGoalSuggestedDailyKcal())
                        })),
                        ChoiceChip(
                          label: const Text("Advanced",
                              style: TextStyle(fontSize: 12.5)),
                          selected: advanced,
                          onSelected: (_) => setL(() => advanced = true),
                        ),
                      ],
                    ),
                    if (advanced) ...[
                      const SizedBox(height: 12),
                      OutlinedButton.icon(
                        icon: const Icon(Icons.event, size: 18),
                        label: Text(targetDate == null
                            ? t("phase_goal_pick_date")
                            : tFmt("phase_goal_date_set", {
                                "d":
                                    "${targetDate!.day}.${targetDate!.month}.${targetDate!.year}"
                              })),
                        onPressed: () async {
                          final d = await showDatePicker(
                            context: ctx,
                            initialDate: targetDate ??
                                today.add(const Duration(days: 42)),
                            firstDate: today.add(const Duration(days: 1)),
                            lastDate: today.add(const Duration(days: 730)),
                          );
                          if (d != null) setL(() => targetDate = d);
                        },
                      ),
                      if (targetDate != null)
                        TextButton(
                          onPressed: () => setL(() => targetDate = null),
                          child: Text(t("phase_goal_no_date")),
                        ),
                      if (targetDate == null) ...[
                        const SizedBox(height: 8),
                        TextField(
                          controller: kcalCtrl,
                          keyboardType: TextInputType.number,
                          decoration: InputDecoration(
                            labelText: bulk
                                ? t("phase_goal_surplus_label")
                                : t("phase_goal_deficit_label"),
                            suffixText: "kcal",
                          ),
                          onChanged: (_) => setL(() {}),
                        ),
                      ],
                    ],
                    const SizedBox(height: 14),
                    Text(t("phase_goal_adjust"),
                        style: const TextStyle(
                            fontSize: 12,
                            fontWeight: FontWeight.w700,
                            color: Color(0xFFC9A24A))),
                    const SizedBox(height: 6),
                    Wrap(
                      spacing: 6,
                      children: [
                        ChoiceChip(
                          label: Text(t("phase_adjust_smart"),
                              style: const TextStyle(fontSize: 12.5)),
                          selected: adjust == "smart",
                          onSelected: (_) => setL(() => adjust = "smart"),
                        ),
                        ChoiceChip(
                          label: Text(t("phase_adjust_fixed"),
                              style: const TextStyle(fontSize: 12.5)),
                          selected: adjust == "fixed",
                          onSelected: (_) => setL(() => adjust = "fixed"),
                        ),
                      ],
                    ),
                    const SizedBox(height: 4),
                    Text(
                      adjust == "smart"
                          ? t("phase_adjust_smart_hint")
                          : t("phase_adjust_fixed_hint"),
                      style: const TextStyle(
                          fontSize: 11.5, color: Colors.white60, height: 1.3),
                    ),
                    if (preview.isNotEmpty) ...[
                      const SizedBox(height: 16),
                      Text(
                        preview,
                        style: const TextStyle(
                          color: Color(0xFFC9A24A),
                          fontWeight: FontWeight.w600,
                          height: 1.4,
                        ),
                      ),
                    ],
                    if (warn.isNotEmpty) ...[
                      const SizedBox(height: 8),
                      Text(warn,
                          style: const TextStyle(
                              color: Color(0xFFE57373), fontSize: 12, height: 1.3)),
                    ],
                    const SizedBox(height: 10),
                    Text(
                      t("phase_goal_info"),
                      style: const TextStyle(
                          color: Colors.white60, fontSize: 11, height: 1.3),
                    ),
                  ],
                ),
              ),
            ),
            actions: [
              if (g != null)
                TextButton(
                  onPressed: () => Navigator.pop(ctx, "delete"),
                  child: Text(
                    t("phase_goal_remove"),
                    style: const TextStyle(color: Color(0xFFE57373)),
                  ),
                ),
              TextButton(
                onPressed: () => Navigator.pop(ctx),
                child: Text(t("cancel")),
              ),
              FilledButton(
                onPressed: (kg >= 0.1 && kc > 0)
                    ? () => Navigator.pop(ctx, "save")
                    : null,
                child: Text(t("save")),
              ),
            ],
          );
        },
      ),
    );
    if (!mounted) return;
    if (result == "delete") {
      await _savePhaseGoal(null);
    } else if (result == "save") {
      final tw = parse(targetCtrl.text) ?? curW;
      final diff = tw - curW;
      final bulk = diff > 0;
      final kg = diff.abs();
      final today = _dateOnlyLocal(DateTime.now());
      double kc;
      if (advanced && targetDate != null) {
        final days = targetDate!.difference(today).inDays;
        kc = days > 0 ? kg * 7000 / days : 0;
      } else if (advanced) {
        kc = parse(kcalCtrl.text) ?? 0;
      } else if (tempo == "plan") {
        kc = _phaseGoalSuggestedDailyKcal();
      } else {
        kc = tempoKcal[tempo] ?? 500;
      }
      final sameKind = g != null && (g["bulk"] == true) == bulk;
      await _savePhaseGoal({
        "kg": kg,
        "bulk": bulk,
        "kcal": kc.roundToDouble(),
        "targetWeight": tw,
        "startWeight": sameKind && g?["startWeight"] is num
            ? g!["startWeight"]
            : curW,
        "adjust": adjust,
        "tempo": advanced ? "custom" : tempo,
        if (advanced && targetDate != null)
          "targetDate": dateKeyFromDate(targetDate!),
        "start": sameKind
            ? (g?["start"] ?? selectedDayKeyToday())
            : selectedDayKeyToday(),
      });
    }
  }

  String selectedDayKeyToday() =>
      dateKeyFromDate(_dateOnlyLocal(DateTime.now()));

  /// Tagesziel-kcal inkl. Cheat (null bei Crashout = keine Defizit-Rechnung).
  double? _goalKcalForStatsDay(String dayKey) {
    if (isCheatDay(dayKey) && cheatDays[dayKey]!.isCrashout) {
      return null;
    }
    final e = effectiveGoalKcalForDay(dayKey);
    if (e < 0) return null;
    if (e == 0) return goalCalories;
    return e;
  }

  /// Grobe Obergrenze Fettverlust / Woche aus KFA-Reserve (Alpert-Ordnung, kcal-Limit).
  double _alpertMaxWeeklyFatLossKg() {
    final fatKg = currentWeightKg * (bodyFatPercent / 100.0);
    if (fatKg < 0.1) return 0.0;
    const kcalPerKgFatPerDay = 69.0;
    return (kcalPerKgFatPerDay * fatKg * 7) / 7000.0;
  }

  /// Obergrenge Zuwachs / Woche (Fett+Muscle-Mix, orientsichungswert im Aufbau).
  double _roughMaxWeeklyGainKg() {
    final fatM = currentWeightKg * (bodyFatPercent / 100.0);
    final leanM = (currentWeightKg - fatM).clamp(1.0, 500.0);
    return (leanM * 0.004 + fatM * 0.0015).clamp(0.1, 0.6);
  }

  /// Wie [mealMacroRangeG]: Gramm = Anteil (min–max %) an **Tagesmenge** (nicht an Rest-kcal).
  ({double minG, double maxG}) dynamicMealMacroRangeG(
      String meal, String macro) {
    if (meal == _kMergedMealCardId) {
      final scope = _activeMergedMealsForDay();
      if (scope == null) return (minG: 0.0, maxG: 0.0);
      var minG = 0.0;
      var maxG = 0.0;
      for (final m in scope) {
        final r = mealMacroRangeG(m, macro);
        minG += r.minG;
        maxG += r.maxG;
      }
      return (minG: minG, maxG: maxG);
    }
    return mealMacroRangeG(meal, macro);
  }

  /// kcal-Spanne der Mahlzeit als Summe der Makro-Min/Max in kcal.
  /// kcal-Zielmitte einer Mahlzeit aus ihren Makro-Anteilen (Mitte).
  double? _mealCenterKcal(String meal) {
    final g = effectiveMacroGoalsForDay(selectedDayKey);
    double kc(String m) {
      final mm = mealMacros[m];
      if (mm == null) return 0;
      return g.protein * (mm["protein"] ?? 0) / 100.0 * 4.1 +
          g.carbs * (mm["carbs"] ?? 0) / 100.0 * 4.1 * _restCarbFactor(m) +
          g.fat * (mm["fat"] ?? 0) / 100.0 * 9.3;
    }

    if (meal == _kWorkoutBlockMealId) {
      return kc("Pre-Workout") + kc("Post-Workout");
    }
    if (!mealMacros.containsKey(meal)) return null;
    return kc(meal);
  }

  ({double minKcal, double maxKcal}) dynamicMealKcalRange(String meal) {
    final p = dynamicMealMacroRangeG(meal, "protein");
    final c = dynamicMealMacroRangeG(meal, "carbs");
    final f = dynamicMealMacroRangeG(meal, "fat");
    return (
      minKcal: p.minG * 4.1 + c.minG * 4.1 + f.minG * 9.3,
      maxKcal: p.maxG * 4.1 + c.maxG * 4.1 + f.maxG * 9.3,
    );
  }

  /// kcal-Spanne aus %-Min/Max je Makro relativ zum Tagesziel in g.
  ({double minKcal, double maxKcal}) _kcalFromMacroPctBands({
    required double pLo,
    required double pHi,
    required double cLo,
    required double cHi,
    required double fLo,
    required double fHi,
  }) {
    final gE = effectiveMacroGoalsForDay(selectedDayKey);
    return (
      minKcal: gE.protein * (pLo / 100.0) * 4.1 +
          gE.carbs * (cLo / 100.0) * 4.1 +
          gE.fat * (fLo / 100.0) * 9.3,
      maxKcal: gE.protein * (pHi / 100.0) * 4.1 +
          gE.carbs * (cHi / 100.0) * 4.1 +
          gE.fat * (fHi / 100.0) * 9.3,
    );
  }

  /// Wie Tageskarte: weiche kcal-Bilanz → skalierte g‑Ziele; pro Mahlzeit × Verteilung-%.
  ({double p, double c, double f}) _balanceRecommendMacroGForMeal(
      String meal) {
    final recK = _recommendKcalForBalanceDisplay(selectedDayKey);
    final bGoal = _dayBaseGoalKcalForDisplay(selectedDayKey);
    final mGoals = effectiveMacroGoalsForDay(selectedDayKey);
    final ratio = bGoal > 0.01 ? (recK / bGoal).clamp(0.5, 1.5) : 1.0;
    final recP = mGoals.protein * ratio;
    final recC = mGoals.carbs * ratio;
    final recF = mGoals.fat * ratio;
    final mm = mealMacros[meal]!;
    return (
      p: recP * (mm['protein']! / 100.0),
      c: recC * (mm['carbs']! / 100.0) * _restCarbFactor(meal),
      f: recF * (mm['fat']! / 100.0),
    );
  }

  /// Pre+Post-Block: gleiche Logik, Anteile summiert.
  ({double p, double c, double f}) _balanceRecommendMacroGForWorkoutBlock() {
    final recK = _recommendKcalForBalanceDisplay(selectedDayKey);
    final bGoal = _dayBaseGoalKcalForDisplay(selectedDayKey);
    final mGoals = effectiveMacroGoalsForDay(selectedDayKey);
    final ratio = bGoal > 0.01 ? (recK / bGoal).clamp(0.5, 1.5) : 1.0;
    final recP = mGoals.protein * ratio;
    final recC = mGoals.carbs * ratio;
    final recF = mGoals.fat * ratio;
    final pre = mealMacros['Pre-Workout']!;
    final post = mealMacros['Post-Workout']!;
    return (
      p: recP * ((pre['protein']! + post['protein']!) / 100.0),
      c: recC * ((pre['carbs']! + post['carbs']!) / 100.0) * _restCarbFactor("Pre-Workout"),
      f: recF * ((pre['fat']! + post['fat']!) / 100.0),
    );
  }

  /// i.d.R. [Evening Meal], sonst letzte in [meals] außer Snacks.
  String? _anchoredLastMealIdForKcal() {
    if (meals.contains("Evening Meal")) return "Evening Meal";
    for (var i = meals.length - 1; i >= 0; i--) {
      if (meals[i] != "Snacks") return meals[i];
    }
    return null;
  }

  /// Anzeige-kcal: für Anker + [lastMealKcalByDay] = Tages-Rest, sonst Makro-Summe.
  ({double minKcal, double maxKcal}) displayMealKcalRangeForUi(String meal) {
    if (meal == _kMergedMealCardId) {
      final scope = _activeMergedMealsForDay();
      if (scope == null) return (minKcal: 0.0, maxKcal: 0.0);
      return _combinedMealKcalRange(scope);
    }
    final anchor = _anchoredLastMealIdForKcal();
    if (anchor == null || meal != anchor) {
      return dynamicMealKcalRange(meal);
    }
    final c = lastMealKcalByDay[selectedDayKey];
    if (c == null || !c.useRemainder) {
      return dynamicMealKcalRange(meal);
    }
    return _remainderKcalRangeForLastMeal(c.reserveSnacks);
  }

  ({double minKcal, double maxKcal}) _remainderKcalRangeForLastMeal(
    bool reserveSnacks,
  ) {
    final anchor = _anchoredLastMealIdForKcal();
    if (anchor == null) {
      return (minKcal: 0.0, maxKcal: 0.0);
    }
    final dr = dailyKcalRange();
    final dayMid = (dr.minKcal + dr.maxKcal) / 2.0;
    var eatenOther = 0.0;
    for (final m in meals) {
      if (m == anchor) continue;
      eatenOther += _mealTotals[m]!['calories'] ?? 0.0;
    }
    var rem = dayMid - eatenOther;
    if (reserveSnacks && meals.contains("Snacks")) {
      final sk = dynamicMealKcalRange("Snacks");
      final sMid = (sk.minKcal + sk.maxKcal) / 2.0;
      final sEaten = _mealTotals["Snacks"]!['calories'] ?? 0.0;
      final sKeep = (sMid - sEaten).clamp(0.0, sMid);
      rem -= sKeep;
    }
    if (dayMid < 1.0) {
      return dynamicMealKcalRange(anchor);
    }
    rem = rem.clamp(0.0, dayMid * 2.0);
    const w = 0.03;
    if (rem < 2.0) {
      return (minKcal: 0.0, maxKcal: 30.0);
    }
    final minK = (rem * (1.0 - w)).clamp(0.0, rem * 1.2);
    final maxK = (rem * (1.0 + w));
    if (maxK <= minK) {
      return (minKcal: rem, maxKcal: rem + 1.0);
    }
    return (minKcal: minK, maxKcal: maxK);
  }

  Future<bool> _ensureLastMealKcalChoiceIfNeeded(String meal) async {
    final anchor = _anchoredLastMealIdForKcal();
    if (anchor == null || meal != anchor) return true;
    if (!lastMealTrackPromptEnabled) return true;
    if (lastMealKcalByDay.containsKey(selectedDayKey)) return true;
    return _showLastMealKcalChoiceDialog();
  }

