  /// Rest-Menge (g) bis **Obergrenze** des Makro-Bands für [meal] (Ziel: Balken auffüllen).
  double? _mealMacroFillGapG(
    String meal,
    String macro, {
    String? preWorkoutCarbKind,
  }) {
    if (macro == "carbs" &&
        meal == "Pre-Workout" &&
        (preWorkoutCarbKind == "komplex" || preWorkoutCarbKind == "einfach")) {
      final gDayM = effectiveMacroGoalsForDay(selectedDayKey);
      final dayCarbG = gDayM.carbs;
      if (dayCarbG <= 0.01) return null;
      // Zielmitte (nicht Maximum).
      final maxG = (preWorkoutCarbKind == "komplex"
              ? dayCarbG * (preCxMin + preCxMax) / 200.0
              : dayCarbG * (preSiMin + preSiMax) / 200.0) *
          _restCarbFactor("Pre-Workout");
      final split = _mealCarbKindSplitG("Pre-Workout");
      final current =
          preWorkoutCarbKind == "komplex" ? split.komplex : split.einfach;
      return (maxG - current).clamp(0.0, 1e9);
    }
    if (_fillDayMode) {
      final g = effectiveMacroGoalsForDay(selectedDayKey);
      final goal = macro == "protein"
          ? g.protein
          : (macro == "carbs" ? g.carbs - _restCarbCutG(selectedDayKey) : g.fat);
      final eaten = trackedFoods
          .where((t) => t.dayKey == selectedDayKey)
          .fold(0.0, (a, t) => a + (macro == "protein" ? t.protein : (macro == "carbs" ? t.carbs : t.fat)));
      return (goal - eaten).clamp(0.0, 1e9);
    }
    final r = dynamicMealMacroRangeG(meal, macro);
    final cur = _mealTotals[meal]![macro] ?? 0.0;
    // Bis zur Zielmitte (goldener Strich = eigene Verteilung) auffüllen.
    final pct = mealMacros[meal]?[macro];
    double target;
    if (pct != null) {
      final gE = effectiveMacroGoalsForDay(selectedDayKey);
      final goalG = macro == "protein"
          ? gE.protein
          : (macro == "carbs" ? gE.carbs : gE.fat);
      target = goalG * pct / 100.0 * (macro == "carbs" ? _restCarbFactor(meal) : 1.0);
    } else {
      target = (r.minG + r.maxG) / 2;
    }
    return (target - cur).clamp(0.0, 1e9);
  }

  /// Rest-kcal bis **Obergrenze** des Mahlzeiten-kcal-Bands.
  double? _mealKcalFillGap(String meal) {
    if (_fillDayMode) {
      final goal = _dayGoalKcalForOverview();
      return (goal - _kcalEatenOnDay(selectedDayKey)).clamp(0.0, 1e9);
    }
    final r = displayMealKcalRangeForUi(meal);
    final cur = _mealTotals[meal]!['calories'] ?? 0.0;
    final center = _mealCenterKcal(meal) ?? (r.minKcal + r.maxKcal) / 2;
    return (center - cur).clamp(0.0, 1e9);
  }

  /// Gramm, sodass [food] ungefähr [gap] g des Ziel-Makros (bzw. kcal) in [meal] deckt.
  double? _fillGramsForTarget(
    Food food,
    String inputMode,
    String meal, {
    String? preWorkoutCarbKind,
  }) {
    if (inputMode == "grams") return null;
    if (inputMode == "kcal") {
      final gap = _mealKcalFillGap(meal);
      if (gap == null || gap <= 0) return null;
      return _gramsFromTrackInputDisplay(food, "kcal", gap);
    }
    if (inputMode == "protein" || inputMode == "carbs" || inputMode == "fat") {
      final macro = inputMode;
      if (macro == "carbs" && meal == "Pre-Workout") {
        final k = preWorkoutCarbKind;
        if (k == "komplex" || k == "einfach") {
          final gap = _mealMacroFillGapG(meal, "carbs", preWorkoutCarbKind: k);
          if (gap == null || gap <= 0) return null;
          return _gramsFromTrackInputDisplay(food, "carbs", gap);
        }
      }
      final gap = _mealMacroFillGapG(meal, macro);
      if (gap == null || gap <= 0) return null;
      return _gramsFromTrackInputDisplay(food, macro, gap);
    }
    return null;
  }

  /// „Balken füllen“: setzt Eingabemodus + angezeigten Wert, oder `null` → Snackbar.
  ({String text, String mode, double value, double grams})? _tryTrackFillField(
    Food food,
    String meal,
    String target, {
    String? preWorkoutCarbKind,
  }) {
    final g = _fillGramsForTarget(food, target, meal,
        preWorkoutCarbKind: preWorkoutCarbKind);
    if (g == null || g <= 0) return null;
    final d = _trackDisplayValueForGrams(food, target, g);
    final v = (d ?? g).roundToDouble();
    return (text: v.toStringAsFixed(0), mode: target, value: v, grams: g);
  }

  @override
  Widget build(BuildContext context) {
    final effectiveIndex = placementDone ? selectedIndex : 0;
    Widget currentScreen;
    switch (effectiveIndex) {
      case 0:
        currentScreen = introScreen();
        break;
      case 1:
        currentScreen = databaseScreen();
        break;
      case 2:
        currentScreen = trackingScreen();
        break;
      case 3:
        currentScreen = settingsScreen();
        break;
      default:
        currentScreen = trackingScreen();
    }

    // Unten nur 3 Punkte: Datenbank · Tracking (Mitte) · Einstellungen.
    // Einleitung liegt jetzt in den Einstellungen.
    const navToScreen = [1, 2, 3];
    final navIndex = switch (effectiveIndex) {
      1 => 0,
      2 => 1,
      _ => 2,
    };
    return Scaffold(
      body: currentScreen,
      bottomNavigationBar: BottomNavigationBar(
        currentIndex: navIndex,
        onTap: (n) {
          final i = navToScreen[n];
          if (!placementDone && i != 0) {
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(
                content: Text(t("placement_gate_msg")),
                behavior: SnackBarBehavior.floating,
              ),
            );
            return;
          }
          setState(() => selectedIndex = i);
        },
        showSelectedLabels: true,
        showUnselectedLabels: true,
        type: BottomNavigationBarType.fixed,
        items: [
          BottomNavigationBarItem(
              icon: const Icon(Icons.storage), label: t("database")),
          BottomNavigationBarItem(
              icon: const Icon(Icons.track_changes), label: t("tracking")),
          BottomNavigationBarItem(
              icon: const Icon(Icons.settings), label: t("settings")),
        ],
      ),
    );
  }

