  Widget _sectionCard({
    required String title,
    required Widget child,
    Widget? titleTrailing,
    Color? color,
    ShapeBorder? shape,
    EdgeInsetsGeometry margin = const EdgeInsets.symmetric(
      horizontal: 8.0,
      vertical: 4.0,
    ),
    /// Titelzeile tippen (z. B. Tagesübersicht → Lebensmittel je Mahlzeit).
    VoidCallback? onTitleTap,
    bool titleSectionExpanded = false,
    Widget? belowTitle,
    /// Nur Titelzeile (schmal, Titel mittig), Inhalt ausgeblendet.
    bool collapsed = false,
  }) {
    return Card(
      margin: margin,
      color: color,
      shape: shape,
      child: Padding(
        padding: collapsed
            ? const EdgeInsets.symmetric(horizontal: 10, vertical: 2)
            : const EdgeInsets.all(10.0),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            if (onTitleTap != null)
              Row(
                crossAxisAlignment: collapsed
                    ? CrossAxisAlignment.center
                    : CrossAxisAlignment.start,
                children: [
                  Expanded(
                    child: InkWell(
                      onTap: onTitleTap,
                      borderRadius: BorderRadius.circular(8),
                      child: Padding(
                        padding: const EdgeInsets.symmetric(vertical: 2),
                        child: Row(
                          children: [
                            Expanded(
                              child: Text(
                                title,
                                style: TextStyle(
                                  fontWeight: FontWeight.bold,
                                  color: context.sol.onCard,
                                ),
                              ),
                            ),
                            Icon(
                              titleSectionExpanded
                                  ? Icons.expand_less
                                  : Icons.expand_more,
                              size: 24,
                              color: context.sol.muted,
                            ),
                          ],
                        ),
                      ),
                    ),
                  ),
                  if (titleTrailing != null) ...[
                    const SizedBox(width: 6),
                    titleTrailing!,
                  ],
                ],
              )
            else
              Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Expanded(
                    child: Text(
                      title,
                      style: TextStyle(
                        fontWeight: FontWeight.bold,
                        color: context.sol.onCard,
                      ),
                    ),
                  ),
                  if (titleTrailing != null) titleTrailing!,
                ],
              ),
            if (belowTitle != null) ...[
              const SizedBox(height: 4),
              belowTitle,
            ],
            if (!collapsed) ...[
              const SizedBox(height: 8),
              child,
            ],
          ],
        ),
      ),
    );
  }

