          row(t("db_hl_protein"), _topPicksProtein(solReorderFilter: tf)),
        if (catF == "Alle" || catF == "Fett")
          row(t("db_hl_fat"), _topPicksFett(solReorderFilter: tf)),
        if (catF == "Alle" || catF == "Ballaststoffe")
