        if (catF == "Alle" || catF == "Carbs") ...[
          row(t("db_hl_carbs_c"), _topPicksCarbsKomplex(solReorderFilter: tf)),
          row(t("db_hl_carbs_s"), _topPicksCarbsEinfach(solReorderFilter: tf)),
        ],
