  /// Kamera-Scan + Open-Food-Facts-API. Kein Vorschau-Dialog.
  Future<_OffFetchResult?> _barcodeOpenFoodLookup() async {
    if (!mounted) return null;
    final code = await showDialog<String>(
      context: context,
      builder: (ctx) => _BarcodeScanDialog(
        t: t,
      ),
    );
    if (code == null || !mounted) return null;
    _OffFetchResult emptyFor(String bc) => _OffFetchResult(
          barcode: bc,
          name: "",
          protein: 0,
          carbs: 0,
          sugar: 0,
          fiber: 0,
          fat: 0,
        );
    if (code == _kBarcodeManualEntry) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(t("barcode_manual_new"))),
      );
      return emptyFor("");
    }
    final cleaned = code.replaceAll(RegExp(r'[^\d]'), '');
    if (cleaned.length < 8) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(t("barcode_manual_new"))),
      );
      return emptyFor("");
    }
    try {
      final uri = Uri.parse(
        "https://world.openfoodfacts.org/api/v2/product/$cleaned.json?fields=product_name,nutriments",
      );
      final res = await http.get(uri);
      if (res.statusCode != 200) throw Exception("HTTP");
      final data = jsonDecode(res.body) as Map<String, dynamic>;
      if (data["status"] != 1) {
        // Nicht in Open Food Facts: trotzdem Formular öffnen (Barcode schon drin),
        // Werte von der Packung eintragen → beim nächsten Scan direkt gefunden.
        if (!mounted) return null;
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text(t("db_off_not_found"))),
        );
        return _OffFetchResult(
          barcode: cleaned,
          name: "",
          protein: 0,
          carbs: 0,
          sugar: 0,
          fiber: 0,
          fat: 0,
        );
      }
      final p = data["product"] as Map<String, dynamic>?;
      if (p == null) return null;
      final n = p["nutriments"] as Map<String, dynamic>? ?? {};
      final name = (p["product_name"] as String?)?.trim() ?? "Food $cleaned";
      double g(String k) {
        final v = n[k];
        if (v is num) return v.toDouble();
        return 0.0;
      }
      if (!mounted) return null;
      final protein = g("proteins_100g");
      final fat = g("fat_100g");
      var carbs = g("carbohydrates_100g");
      final su = g("sugars_100g");
      final fi = g("fiber_100g");
      if (carbs <= 0 && (protein + fat) > 0) {
        carbs = 0.1;
      }
      return _OffFetchResult(
        barcode: cleaned,
        name: name,
        protein: protein,
        carbs: carbs,
        sugar: su,
        fiber: fi,
        fat: fat,
      );
    } catch (_) {
      if (!mounted) return null;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(t("barcode_manual_new"))),
      );
      return emptyFor(cleaned);
    }
  }

  /// Open Food Facts → ggf. vorhandenes Lebensmittel → sonst Vorschau → DB.
  Future<void> _openBarcodeAddFlow() async {
    final fetch = await _barcodeOpenFoodLookup();
    if (fetch == null) return;
    final code = fetch.barcode;
    Food? hit;
    for (final f in foodDatabase) {
      if (code.isNotEmpty && f.offBarcode == code) {
        hit = f;
        break;
      }
    }
    if (hit != null && mounted) {
      final foundFood = hit;
      final a = await showDialog<String>(
        context: context,
        builder: (ctx) => AlertDialog(
          backgroundColor: const Color(0xFF1E1E1E),
          title: Text(t("barcode_food_in_db_title")),
          content: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Text(
                  t("barcode_food_in_db_body"),
                  style: const TextStyle(height: 1.35),
                ),
                const SizedBox(height: 12),
                _foodCompareCard(foundFood),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(ctx, "cancel"),
              child: Text(t("cancel"), style: const TextStyle(color: Colors.white60)),
            ),
            TextButton(
              onPressed: () => Navigator.pop(ctx, "new"),
              child: Text(t("barcode_new_copy"), style: const TextStyle(color: Colors.white70)),
            ),
            FilledButton(
              onPressed: () => Navigator.pop(ctx, "track"),
              child: Text(t("barcode_add_to_track")),
            ),
          ],
        ),
      );
      if (a == "track") {
        await _quickAddScannedFoodToTracking(foundFood);
        return;
      }
      if (a != "new") return;
    }
    await _showOffPreviewFromOff(fetch);
  }

  /// Nach Barcode-Scan: Mahlzeit wählen (oder [fixedMeal]), Menge, sofort im Tracking.
  /// [popSecondContext]: z. B. „Food hinzufügen“-Dialog — nach dem Hinzufügen schließen.
  Future<void> _quickAddScannedFoodToTracking(
    Food food, {
    String? fixedMeal,
    BuildContext? popSecondContext,
  }) async {
    if (meals.isEmpty) return;
    var meal = fixedMeal != null && meals.contains(fixedMeal)
        ? fixedMeal
        : (meals.contains("Snacks") ? "Snacks" : meals.first);
    final g = TextEditingController(text: "100");
    var inputMode = "grams";
    if (!mounted) return;
    final useMealPicker = fixedMeal == null || !meals.contains(fixedMeal);
    await showDialog<void>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setL) {
          void applyMealFill(String mode, {String? preCarb}) {
            final gFill = _fillGramsForTarget(food, mode, meal,
                preWorkoutCarbKind: preCarb);
            if (gFill == null || gFill <= 0) {
              if (!context.mounted) return;
              ScaffoldMessenger.of(context).showSnackBar(
                SnackBar(content: Text(t("track_fill_none"))),
              );
              return;
            }
            setL(() {
              inputMode = mode;
              final d = _trackDisplayValueForGrams(food, mode, gFill);
              g.text = (d ?? gFill).round().toString();
            });
          }
          return AlertDialog(
          backgroundColor: const Color(0xFF1E1E1E),
          title: Text(t("barcode_add_to_track")),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                food.name,
                style: const TextStyle(fontWeight: FontWeight.w600),
              ),
              const SizedBox(height: 10),
              if (useMealPicker) ...[
                DropdownButtonFormField<String>(
                  value: meal,
                  isExpanded: true,
                  decoration: _touchInputDecoration(t("meal")),
                  items: meals
                      .map(
                        (m) => DropdownMenuItem(
                          value: m,
                          child: Text(_displayMealName(m)),
                        ),
                      )
                      .toList(),
                  onChanged: (v) {
                    if (v != null) setL(() => meal = v);
                  },
                ),
                const SizedBox(height: 10),
              ] else ...[
                Align(
                  alignment: Alignment.centerLeft,
                  child: Text(
                    "${t("meal")}: ${_displayMealName(meal)}",
                    style: const TextStyle(
                      fontSize: 13.5,
                      color: Colors.white70,
                    ),
                  ),
                ),
                const SizedBox(height: 10),
              ],
              Text(
                t("track_input_mode"),
                style: const TextStyle(
                  color: Colors.white70,
                  fontSize: 12,
                  fontWeight: FontWeight.w600,
                ),
              ),
              const SizedBox(height: 4),
              DropdownButtonFormField<String>(
                value: inputMode,
                isExpanded: true,
                decoration: _touchInputDecoration(t("track_input_mode")),
                items: [
                  DropdownMenuItem(
                    value: "grams",
                    child: Text(t("track_mode_grams")),
                  ),
                  if (food.calories > 0.01)
                    DropdownMenuItem(
                      value: "kcal",
                      child: Text(t("track_mode_kcal")),
                    ),
                  if (food.protein > 0.01)
                    DropdownMenuItem(
                      value: "protein",
                      child: Text(t("track_mode_protein")),
                    ),
                  if (food.carbs > 0.01)
                    DropdownMenuItem(
                      value: "carbs",
                      child: Text(t("track_mode_carbs")),
                    ),
                  if (food.fat > 0.01)
                    DropdownMenuItem(
                      value: "fat",
                      child: Text(t("track_mode_fat")),
                    ),
                ],
                onChanged: (v) {
                  if (v == null) return;
                  setL(() => inputMode = v);
                },
              ),
              const SizedBox(height: 6),
              Align(
                alignment: Alignment.centerLeft,
                child: Text(
                  t("track_fill_group_label"),
                  style: const TextStyle(
                    fontSize: 11.5,
                    color: Color(0xFFFFB74D),
                    fontWeight: FontWeight.w600,
                  ),
                ),
              ),
              const SizedBox(height: 4),
              Wrap(
                spacing: 5,
                runSpacing: 4,
                children: [
                  if (food.protein > 0.01)
                    ActionChip(
                      label: Text(
                        t("track_fill_protein"),
                        style: const TextStyle(fontSize: 11.5),
                      ),
                      onPressed: () => applyMealFill("protein"),
                    ),
                  if (food.carbs > 0.01 && meal != "Pre-Workout")
                    ActionChip(
                      label: Text(
                        t("track_fill_carbs"),
                        style: const TextStyle(fontSize: 11.5),
                      ),
                      onPressed: () => applyMealFill("carbs"),
                    ),
                  if (meal == "Pre-Workout" && food.carbs > 0.01) ...[
                    ActionChip(
                      label: Text(
                        t("track_fill_carb_complex"),
                        style: const TextStyle(fontSize: 11.5),
                      ),
                      onPressed: () => applyMealFill("carbs", preCarb: "komplex"),
                    ),
                    ActionChip(
                      label: Text(
                        t("track_fill_carb_simple"),
                        style: const TextStyle(fontSize: 11.5),
                      ),
                      onPressed: () => applyMealFill("carbs", preCarb: "einfach"),
                    ),
                  ],
                  if (food.fat > 0.01)
                    ActionChip(
                      label: Text(
                        t("track_fill_fat"),
                        style: const TextStyle(fontSize: 11.5),
                      ),
                      onPressed: () => applyMealFill("fat"),
                    ),
                  if (food.calories > 0.01)
                    ActionChip(
                      label: Text(
                        t("track_fill_kcal"),
                        style: const TextStyle(fontSize: 11.5),
                      ),
                      onPressed: () => applyMealFill("kcal"),
                    ),
                ],
              ),
              const SizedBox(height: 8),
              TextField(
                controller: g,
                onChanged: (_) => setL(() {}),
                keyboardType:
                    const TextInputType.numberWithOptions(decimal: true),
                decoration: _touchInputDecoration(t("track_value_label")),
              ),
            ],
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: Text(t("cancel")),
            ),
            FilledButton(
              onPressed: () {
                final gv = _gramsForTrackedAdd(food, inputMode, g.text);
                if (gv == null || gv <= 0) return;
                setState(() {
                  trackedFoods.add(
                    TrackedFood(
                      food: food,
                      grams: gv,
                      meal: meal,
                      dayKey: selectedDayKey,
                    ),
                  );
                });
                _updateMealTotals();
                _saveAppState();
                Navigator.pop(ctx);
                if (popSecondContext != null && popSecondContext.mounted) {
                  Navigator.pop(popSecondContext);
                }
                _showBlessing();
                _applyDailyKcalOverSchedule();
              },
              child: Text(t("add")),
            ),
          ],
        );
        },
      ),
    );
  }

  /// Nährwerte prüfen, in [foodDatabase] speichern; Rückgabe des neuen [Food] für z. B. Tracking.
  Future<Food?> _showOffPreviewFromOff(_OffFetchResult r) async {
    final p = TextEditingController(text: _fmtEdit1(r.protein));
    final c = TextEditingController(text: _fmtEdit1(r.carbs));
    final s = TextEditingController(text: _fmtEdit1(r.sugar));
    final fi = TextEditingController(text: _fmtEdit1(r.fiber));
    final f = TextEditingController(text: _fmtEdit1(r.fat));
    final nCtrl = TextEditingController(text: r.name);
    if (!mounted) return null;
    String saveCat = "Carbs";
    String saveCK = "komplex";
    String saveType = "Diät (Viel Volumen)";
    String? saveFlavor;
    String? savedImagePath;
    String? stagedPickPath;
    return showDialog<Food?>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (context, setL) => AlertDialog(
          title: Text(t("db_off_preview_title")),
          content: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  r.barcode,
                  style: const TextStyle(fontSize: 11, color: Colors.white38),
                ),
                const SizedBox(height: 16),
                TextField(
                  controller: nCtrl,
                  decoration: _touchInputDecoration(t("name")),
                ),
                const SizedBox(height: 14),
                DropdownButtonFormField<String>(
                  value: saveCat,
                  decoration: _touchInputDecoration(t("db_off_category")),
                  items: [
                    "Carbs",
                    "Protein",
                    "Fett",
                    "Ballaststoffe",
                  ]
                      .map(
                        (e) => DropdownMenuItem(
                          value: e,
                          child: Text(_tCat(e)),
                        ),
                      )
                      .toList(),
                  onChanged: (v) {
                    if (v == null) return;
                    setL(() {
                      saveCat = v;
                    });
                  },
                ),
                if (saveCat == "Carbs")
                  ListTile(
                    contentPadding: EdgeInsets.zero,
                    title: Text(
                      t("db_carb_source_tile"),
                      style: const TextStyle(
                          fontSize: 14, fontWeight: FontWeight.w600),
                    ),
                    subtitle: Text(
                      "${saveCK == "komplex" ? t("carb_tag_complex") : t("carb_tag_simple")} · ${t("db_carb_source_tile_sub")}",
                      style: const TextStyle(
                          fontSize: 11, color: Colors.white60),
                    ),
                    trailing:
                        const Icon(Icons.chevron_right, color: Colors.white38),
                    onTap: () async {
                      final p =
                          await _showCarbSourceBottomSheet(current: saveCK);
                      if (p != null) setL(() => saveCK = p);
                    },
                  ),
                const SizedBox(height: 14),
                DropdownButtonFormField<String>(
                  value: saveType,
                  decoration: _touchInputDecoration(t("type")),
                  items: [
                    "Diät (Viel Volumen)",
                    "Aufbau (Wenig Volumen)",
                  ]
                      .map(
                        (e) => DropdownMenuItem(
                          value: e,
                          child: Text(_tFullType(e)),
                        ),
                      )
                      .toList(),
                  onChanged: (v) {
                    if (v == null) return;
                    setL(() => saveType = v);
                  },
                ),
                const SizedBox(height: 14),
                DropdownButtonFormField<String?>(
                  value: saveFlavor,
                  decoration: _touchInputDecoration(
                      t("recipe_flavor_filter_label")),
                  items: <DropdownMenuItem<String?>>[
                    DropdownMenuItem<String?>(
                      value: null,
                      child: Text(t("food_flavor_none")),
                    ),
                    DropdownMenuItem<String?>(
                      value: "sweet",
                      child: Text(t("recipe_flavor_sweet")),
                    ),
                    DropdownMenuItem<String?>(
                      value: "salty",
                      child: Text(t("recipe_flavor_salty")),
                    ),
                  ],
                  onChanged: (v) {
                    setL(() => saveFlavor = v);
                  },
                ),
                const SizedBox(height: 14),
                Text(
                  t("values_per_100g"),
                  style: const TextStyle(fontSize: 12),
                ),
                const SizedBox(height: 14),
                TextField(
                    controller: p,
                    keyboardType: const TextInputType.numberWithOptions(
                        decimal: true),
                    decoration: _touchInputDecoration(t("protein"))),
                const SizedBox(height: 14),
                TextField(
                    controller: c,
                    keyboardType: const TextInputType.numberWithOptions(
                        decimal: true),
                    decoration: _touchInputDecoration(t("carbs_total"))),
                const SizedBox(height: 14),
                TextField(
                    controller: s,
                    keyboardType: const TextInputType.numberWithOptions(
                        decimal: true),
                    decoration: _touchInputDecoration(t("of_which_sugar"))),
                const SizedBox(height: 14),
                TextField(
                    controller: fi,
                    keyboardType: const TextInputType.numberWithOptions(
                        decimal: true),
                    decoration: _touchInputDecoration(t("of_which_fiber"))),
                const SizedBox(height: 14),
                TextField(
                    controller: f,
                    keyboardType: const TextInputType.numberWithOptions(
                        decimal: true),
                    decoration: _touchInputDecoration(t("fat"))),
                const SizedBox(height: 10),
                _userFoodImagePickerSection(
                  savedImagePath: savedImagePath,
                  stagedPickPath: stagedPickPath,
                  onSavedImagePathChanged: (v) => setL(() => savedImagePath = v),
                  onStagedPickPathChanged: (v) => setL(() => stagedPickPath = v),
                ),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: Text(t("cancel")),
            ),
            TextButton(
              onPressed: () async {
                final pV = _tryParseUserNumber(p.text);
                final cV = _tryParseUserNumber(c.text);
                final sV = _tryParseUserNumber(s.text);
                final fiV = _tryParseUserNumber(fi.text);
                final fV = _tryParseUserNumber(f.text);
                if (nCtrl.text.trim().isEmpty ||
                    pV == null ||
                    cV == null ||
                    sV == null ||
                    fiV == null ||
                    fV == null) {
                  return;
                }
                final byBar = _findAnyFoodByBarcodeInDatabase(r.barcode);
                if (byBar != null) {
                  await _showBarcodeAlreadyInDatabase(byBar);
                  return;
                }
                final byName = _findUserFoodByNormalizedName(nCtrl.text.trim());
                if (byName != null) {
                  if (!await _confirmDuplicateUserFoodName(byName)) {
                    return;
                  }
                  if (!mounted) return;
                }
                final img = await _resolveUserFoodImagePath(
                  foodName: nCtrl.text.trim(),
                  savedImagePath: savedImagePath,
                  stagedPickPath: stagedPickPath,
                );
                final newFood = Food(
                  name: nCtrl.text.trim(),
                  protein: pV,
                  carbs: cV,
                  sugar: sV,
                  fiber: fiV,
                  fat: fV,
                  category: saveCat,
                  type: saveType,
                  isDefault: false,
                  carbKind: saveCat == "Carbs" ? saveCK : null,
                  recipeFlavor: saveFlavor,
                  offBarcode: r.barcode.isEmpty ? null : r.barcode,
                  imagePath: img,
                );
                setState(() {
                  foodDatabase.add(newFood);
                });
                _saveAppState();
                if (ctx.mounted) Navigator.pop(ctx, newFood);
              },
              child: Text(t("save")),
            ),
          ],
        ),
      ),
    );
  }

