      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Container(
          decoration: inWizardGroup
              ? null
              : BoxDecoration(
                  borderRadius: r,
                  boxShadow: const [
                    BoxShadow(
                      color: Color(0x33000000),
                      blurRadius: 6,
                      offset: Offset(0, 1),
                    ),
                  ],
                ),
          child: ClipRRect(
            borderRadius: r,
            child: Container(
              height: 200,
              decoration: BoxDecoration(
                color: inWizardGroup
                    ? const Color(0xFF0A0806)
                    : const Color(0xFF0D0C0A),
                border: inWizardGroup
                    ? null
                    : Border.all(
                        color: const Color(0x8AC9A24A),
                        width: 0.8,
                      ),
              ),
              child: Theme(
                data: Theme.of(listContext).copyWith(
                  scrollbarTheme: ScrollbarThemeData(
                    thickness: WidgetStateProperty.all(6),
                    radius: const Radius.circular(3),
                    thumbColor: WidgetStateProperty.all(
                      const Color(0xCCC9A24A).withValues(alpha: 0.75),
                    ),
                    trackColor: WidgetStateProperty.all(
                      const Color(0xFF1E1C19),
                    ),
                    trackBorderColor: WidgetStateProperty.all(
                      const Color(0xFF4A3F2A),
                    ),
                  ),
                ),
                child: Scrollbar(
                  controller: controller,
                  trackVisibility: true,
                  thickness: 6,
                  child: ListView(
                    controller: controller,
                    padding: const EdgeInsets.fromLTRB(0, 0, 2, 6),
                    children: children,
                  ),
                ),
              ),
            ),
          ),
        ),
      ],
    );
  }

