                    padding: const EdgeInsets.fromLTRB(8, 4, 8, 6),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.stretch,
                      children: [
                        _ringOverview(
                          eaten: totalCalories,
                          goal: () {
                            if (!isCheatDay(selectedDayKey)) {
      return goalCalories - _restCarbCutG(selectedDayKey) * 4.1;
    }
                            if (isSelectedDayCrashout) return goalCalories;
                            final eff = effectiveGoalKcalForDay(selectedDayKey);
                            return eff > 0 ? eff : goalCalories;
                          }(),
                          protein: totalProtein,
                          carbs: totalCarbs,
                          fat: totalFat,
                        ),
                        _dayMacroDetails(
                          recK: recK,
                          totalProtein: totalProtein,
                          totalCarbs: totalCarbs,
                          totalFat: totalFat,
                        ),
                        if (phaseGoal == null)
                          Align(
                            alignment: Alignment.center,
                            child: TextButton(
                              style: TextButton.styleFrom(
                                visualDensity: VisualDensity.compact,
                                foregroundColor: const Color(0xFFC9A24A),
