  /// Fallback, wenn kein Emoji (z. B. nur Icon nötig).
  IconData _mealSlotIcon(String mealId) {
    switch (mealId) {
      case "Snacks":
        return Icons.cookie_outlined;
      case "Workout":
      case "Pre-Workout":
      case "Post-Workout":
        return Icons.fitness_center;
      case "Main Meal":
        return Icons.outdoor_grill;
      case "Evening Meal":
        return Icons.dinner_dining;
      default:
        return Icons.restaurant_menu;
    }
  }

  /// KH in g (komplex / einfach) pro Mahlzeit — [Food.carbKind] bzw. Heuristik.
  ({double komplex, double einfach}) _mealCarbKindSplitG(String meal) {
    var k = 0.0;
    var e = 0.0;
    for (final f in trackedFoods) {
      if (f.meal != meal || f.dayKey != selectedDayKey) continue;
      // Zucker = einfache KH. Rest der KH = komplex.
      // Ohne Zucker-Angabe: wie bisher nach Lebensmittel-Art.
      final sugar = f.sugar.clamp(0.0, f.carbs).toDouble();
      if (sugar > 0.01) {
        e += sugar;
        k += f.carbs - sugar;
      } else if (_inferredCarbKind(f.food) == "einfach") {
        e += f.carbs;
      } else {
        k += f.carbs;
      }
    }
    return (komplex: k, einfach: e);
  }

