              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Expanded(
                  child: Material(
                    color: Colors.transparent,
                    child: Tooltip(
                      message: t("workout_block_title_tooltip"),
                      child: InkWell(
                        onTap: () {
                          if (!mounted) return;
                          _openWorkoutBlockBottomSheet();
