  /// Kompakte Makro-Kachel für getrackte Portionen (ausgeschriebene Namen).
  Widget _trackedMacroPill({
    required String label,
    required double grams,
    required Color color,
  }) {
    return Expanded(
      child: Container(
        padding: const EdgeInsets.symmetric(vertical: 4, horizontal: 5),
        decoration: BoxDecoration(
          color: color.withValues(alpha: 0.1),
          borderRadius: BorderRadius.circular(6),
          border: Border.all(color: color.withValues(alpha: 0.28)),
        ),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            // Zahl oben, Bezeichnung darunter.
            Text(
              "${grams.toStringAsFixed(0)} g",
              style: TextStyle(
                color: color,
                fontSize: 12,
                fontWeight: FontWeight.w800,
                height: 1.1,
                fontFeatures: const [FontFeature.tabularFigures()],
              ),
            ),
            const SizedBox(height: 1),
            Text(
              label,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(
                color: color.withValues(alpha: 0.9),
                fontSize: 9,
                fontWeight: FontWeight.w600,
                height: 1.1,
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _trackedFoodPcfRow({
    required double protein,
    required double carbs,
    required double fat,
  }) {
    return Row(
      children: [
        _trackedMacroPill(
          label: t("protein"),
          grams: protein,
          color: _proteinColor,
        ),
        const SizedBox(width: 4),
        _trackedMacroPill(
          label: t("carbs"),
          grams: carbs,
          color: _carbColor,
        ),
        const SizedBox(width: 4),
        _trackedMacroPill(
          label: t("fat"),
          grams: fat,
          color: _fatColor,
        ),
      ],
    );
  }

  /// Eine Portion: g/kcal + P/k/F + Zucker/Ballaststoffe (Popup-Liste).
  Widget _mealTrackedListItemSubtitle(TrackedFood f) {
    final muted = context.sol.muted;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      mainAxisSize: MainAxisSize.min,
      children: [
        Text.rich(
          TextSpan(
            style: TextStyle(
              fontSize: 12,
              height: 1.2,
              fontFeatures: const [FontFeature.tabularFigures()],
            ),
            children: [
              TextSpan(
                text: "${f.grams.toStringAsFixed(0)} g",
                style: TextStyle(
                  color: context.sol.onCard,
                  fontWeight: FontWeight.w600,
                ),
              ),
              TextSpan(text: " · ", style: TextStyle(color: muted)),
              TextSpan(
                text: "${f.calories.toStringAsFixed(0)} kcal",
                style: const TextStyle(
                  color: Color(0xFFC9A24A),
                  fontWeight: FontWeight.w700,
                ),
              ),
            ],
          ),
        ),
        const SizedBox(height: 5),
        _trackedFoodPcfRow(
          protein: f.protein,
          carbs: f.carbs,
          fat: f.fat,
        ),
        if (f.sugar > 0.05 || f.fiber > 0.05) ...[
          const SizedBox(height: 4),
          Text(
            "${t("of_which_sugar")} ${f.sugar.toStringAsFixed(0)} · ${t("of_which_fiber")} ${f.fiber.toStringAsFixed(0)} g",
            style: TextStyle(
              color: muted.withValues(alpha: 0.85),
              fontSize: 10,
              height: 1.2,
              fontFeatures: const [FontFeature.tabularFigures()],
            ),
          ),
        ],
      ],
    );
  }

