  void _openWorkoutBlockBottomSheet() {
    if (!mounted) return;
    showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: context.sol.card,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.all(Radius.circular(16)),
      ),
      builder: (ctx) {
        return StatefulBuilder(
          builder: (ctx, setModalState) {
            final bottomPad = MediaQuery.viewPaddingOf(ctx).bottom;
            // Extra unten: Safe-Home-Indicator + sichtbarer Abstand, nicht anliegend
            final h = MediaQuery.sizeOf(ctx).height;
            const workoutSheetBottomGutter = 48.0;
            final workoutSheetViewportGap = h * 0.10;
            return DraggableScrollableSheet(
              expand: false,
              initialChildSize: 0.78,
              minChildSize: 0.38,
              maxChildSize: 0.94,
              // Live: jede Änderung (hinzufügen, löschen, bearbeiten) sofort zeigen.
              builder: (ctx, scrollController) => ValueListenableBuilder<int>(
                valueListenable: _liveRev,
                builder: (ctx, _, __) {
                return Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Center(
                      child: Container(
                        width: 40,
                        height: 4,
                        margin: const EdgeInsets.only(top: 8, bottom: 4),
                        decoration: BoxDecoration(
                          color: context.sol.soft.withValues(alpha: 0.4),
                          borderRadius: BorderRadius.circular(2),
                        ),
                      ),
                    ),
                    Padding(
                      padding: const EdgeInsets.fromLTRB(16, 4, 8, 4),
                      child: Row(
                        children: [
                          const Icon(
                            Icons.fitness_center,
                            color: Color(0xFFC9A24A),
                            size: 24,
                          ),
                          const SizedBox(width: 10),
                          Expanded(
                            child: Text(
                              t("tracking_workout_popup_title"),
                              style: TextStyle(
                                fontWeight: FontWeight.w800,
                                fontSize: 17,
                                color: context.sol.onCard,
                              ),
                            ),
                          ),
                          IconButton(
                            tooltip: t("cancel"),
                            onPressed: () => Navigator.of(ctx).pop(),
                            icon: Icon(Icons.close, color: context.sol.muted),
                          ),
                        ],
                      ),
                    ),
                    const Divider(height: 1),
                    Expanded(
                      child: ListView(
                        controller: scrollController,
                        padding: EdgeInsets.fromLTRB(
                          8,
                          12,
                          8,
                          36 +
                              bottomPad +
                              workoutSheetBottomGutter +
                              workoutSheetViewportGap,
                        ),
                        children: [
                          _buildMealSectionCard(
                            "Pre-Workout",
                            sectionCardMargin: const EdgeInsets.fromLTRB(
                              0,
                              0,
                              0,
                              8,
                            ),
                            onAfterExpandToggle: () => setModalState(() {}),
                          ),
                          _buildMealSectionCard(
                            "Post-Workout",
                            sectionCardMargin: EdgeInsets.zero,
                            onAfterExpandToggle: () => setModalState(() {}),
                          ),
                        ],
                      ),
                    ),
                  ],
                );
              }),
            );
          },
        );
      },
    );
  }

  void _openMealTrackedListPopup(String meal) {
    if (!mounted) return;
    showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: context.sol.card,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.all(Radius.circular(16)),
      ),
      builder: (ctx) {
        final bottomPad = MediaQuery.viewPaddingOf(ctx).bottom;
        // Unten extra Luft (Home-Indicator, nicht anliegend).
        const mealTrackedSheetBottomGutter = 48.0;
        return DraggableScrollableSheet(
          expand: false,
          initialChildSize: 0.5,
          minChildSize: 0.32,
          maxChildSize: 0.88,
          builder: (ctx, scrollController) => ValueListenableBuilder<int>(
            valueListenable: _liveRev,
            builder: (ctx, _, __) {
            _updateMealTotals();
            final items = trackedFoods
                .where((f) => f.meal == meal && f.dayKey == selectedDayKey)
                .toList();
            return Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Center(
                  child: Container(
                    width: 40,
                    height: 4,
                    margin: const EdgeInsets.only(top: 8, bottom: 4),
                    decoration: BoxDecoration(
                      color: context.sol.soft.withValues(alpha: 0.4),
                      borderRadius: BorderRadius.circular(2),
                    ),
                  ),
                ),
                Padding(
                  padding: const EdgeInsets.fromLTRB(16, 4, 8, 8),
                  child: Row(
                    children: [
                      _mealSlotLeading(meal),
                      const SizedBox(width: 10),
                      Expanded(
                        child: Text(
                          tFmt("meal_tracked_popup_title", {
                            "m": _displayMealName(meal),
                          }),
                          style: TextStyle(
                            fontWeight: FontWeight.w800,
                            fontSize: 17,
                            color: context.sol.onCard,
                          ),
                        ),
                      ),
                      IconButton(
                        tooltip: t("cancel"),
                        onPressed: () => Navigator.of(ctx).pop(),
                        icon: Icon(Icons.close, color: context.sol.muted),
                      ),
                    ],
                  ),
                ),
                if (items.isNotEmpty)
                  _mealTrackedPopupMealTotals(meal, count: items.length),
                if (items.isEmpty)
                  Padding(
                    padding: EdgeInsets.fromLTRB(
                      20,
                      20,
                      20,
                      32 + bottomPad + mealTrackedSheetBottomGutter,
                    ),
                    child: Center(
                      child: Text(
                        t("meal_tracked_empty"),
                        textAlign: TextAlign.center,
                        style: TextStyle(
                          color: context.sol.muted,
                          fontSize: 14,
                        ),
                      ),
                    ),
                  )
                else
                  Expanded(
                    child: ListView.separated(
                      controller: scrollController,
                      padding: EdgeInsets.fromLTRB(
                        12,
                        0,
                        12,
                        32 + bottomPad + mealTrackedSheetBottomGutter,
                      ),
                      itemCount: items.length,
                      separatorBuilder: (_, __) => const SizedBox(height: 6),
                      itemBuilder: (c, i) {
                        final f = items[i];
                        // Antippen → Lebensmittel/Rezept nochmal ansehen.
                        return GestureDetector(
                          behavior: HitTestBehavior.opaque,
                          onTap: () => _showRecipeInfoDialog(
                              _foodByName(f.food.name) ?? f.food),
                          child: Container(
                          padding: const EdgeInsets.fromLTRB(8, 6, 2, 6),
                          decoration: BoxDecoration(
                            color: Colors.white.withValues(alpha: 0.04),
                            borderRadius: BorderRadius.circular(8),
                            border: Border.all(
                              color: context.sol.soft.withValues(alpha: 0.22),
                            ),
                          ),
                          child: Row(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Expanded(
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    Text(
                                      f.food.name,
                                      style: TextStyle(
                                        color: context.sol.onCard,
                                        fontWeight: FontWeight.w700,
                                        fontSize: 14,
                                        height: 1.15,
                                      ),
                                    ),
                                    const SizedBox(height: 4),
                                    _mealTrackedListItemSubtitle(f),
                                  ],
                                ),
                              ),
                              Row(
                                mainAxisSize: MainAxisSize.min,
                                children: [
                                  IconButton(
                                    visualDensity: VisualDensity.compact,
                                    padding: EdgeInsets.zero,
                                    constraints: const BoxConstraints(
                                      minWidth: 36,
                                      minHeight: 36,
                                    ),
                                    icon: const Icon(
                                      Icons.edit_outlined,
                                      color: Color(0xFFC9A24A),
