                            ),
                            onPressed: hasChange
                                ? () {
                                    setState(() {
                                      alltagBalance = _alltagBalanceDraft;
                                      _applyAlltagMealDistribution();
                                      _applyAutoNutritionTargets();
                                    });
                                    _saveAppState();
                                    ScaffoldMessenger.of(context).showSnackBar(
                                      SnackBar(
