                            setState(() {
                              mealMacros[selectedMeal]!["protein"] = pVal;
                              mealMacros[selectedMeal]!["carbs"] = cVal;
                              mealMacros[selectedMeal]!["fat"] = fVal;
                            });
                            _saveAppState();
                            setDialogState(() {});
                            _updateMealTotals();
