  Future<void> _resetSelectedDayTracking() async {
    final shouldReset = await showDialog<bool>(
          context: context,
          builder: (_) => AlertDialog(
            title: Text(t("reset_day_title")),
            content: Text("${t("reset_day_body")} ($selectedDayKey)"),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(context, false),
                child: Text(t("cancel")),
              ),
              TextButton(
                onPressed: () => Navigator.pop(context, true),
                child: Text(t("reset")),
              ),
            ],
          ),
        ) ??
        false;
    if (!shouldReset) return;
    setState(() {
      trackedFoods.removeWhere((t) => t.dayKey == selectedDayKey);
      lastMealKcalByDay.remove(selectedDayKey);
    });
    _saveAppState();
    _applyDailyKcalOverSchedule();
  }

  Future<void> _openDayNoteDialog() async {
    final ctrl = TextEditingController(text: dayNotes[selectedDayKey] ?? "");
    await showDialog(
      context: context,
      builder: (_) => AlertDialog(
        title: Text("${t("day_note")} ($selectedDayKey)"),
        content: TextField(
          controller: ctrl,
          autofocus: true,
          maxLines: 6,
          minLines: 3,
          decoration: _touchInputDecoration(t("note_hint")),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: Text(t("cancel")),
          ),
          TextButton(
            onPressed: () {
              final text = ctrl.text.trim();
              setState(() {
                if (text.isEmpty) {
                  dayNotes.remove(selectedDayKey);
                } else {
                  dayNotes[selectedDayKey] = text;
                }
              });
              _saveAppState();
              Navigator.pop(context);
            },
            child: Text(t("save")),
          ),
        ],
      ),
    );
  }

  Future<void> _openMealNoteDialog(String meal) async {
    final key = selectedDayKey;
    final initial = List<MealNoteLine>.from(
      mealDayNoteLists[key]?[meal] ?? const <MealNoteLine>[],
    );
    final result = await showDialog<List<MealNoteLine>>(
      context: context,
      builder: (ctx) => _MealNoteChecklistDialog(
        dayKey: key,
        mealLabel: _displayMealName(meal),
        initial: initial,
        t: t,
      ),
    );
    if (!mounted) return;
    if (result == null) return;
    setState(() {
      if (result.isEmpty) {
        final m = mealDayNoteLists[key];
        if (m != null) {
          m.remove(meal);
          if (m.isEmpty) {
            mealDayNoteLists.remove(key);
          }
        }
      } else {
        mealDayNoteLists.putIfAbsent(key, () => {})[meal] = result;
      }
    });
    _saveAppState();
  }

  /// Max. 2× pro Tag beim App-Start, wenn noch keine Waage.
  Future<void> _nudgeWeightOnAppOpen() async {
    if (!mounted) return;
    final k = dateKeyFromDate(DateTime.now());
    if (weightHistory.containsKey(k)) return;
    // Morgen-Abfrage lief heute schon / läuft gerade → nicht nochmal fragen.
    if (_weightDialogOpen || _lastAutoWeightPromptDay == k) return;
    final prefs = await SharedPreferences.getInstance();
    Map<String, int> m = {};
    final raw = prefs.getString(_kWeightOpenCountByDayKey);
    if (raw != null && raw.isNotEmpty) {
      try {
        m = Map<String, int>.from(
          (jsonDecode(raw) as Map).map(
            (a, b) => MapEntry(a.toString(), (b is int) ? b : int.parse(b.toString())),
          ),
        );
      } catch (_) {}
    }
    final c = m[k] ?? 0;
    if (c >= 2) return;
    m[k] = c + 1;
    await prefs.setString(_kWeightOpenCountByDayKey, jsonEncode(m));
    if (!mounted) return;
    if (_weightDialogOpen || weightHistory.containsKey(k)) return;
    await _openWeightDialog(forDayKey: k);
  }

  /// Tageskcal über Ziel: Optionen (Extra‑Schritte, Cheatday, ignorieren) — ein Mal pro erneutem «drüber»-Zustand (Prefs wird unter Ziel gelöscht).
  Future<void> _checkDailyKcalOver() async {
    if (!mounted) return;
    if (_dailyOverDialogInFlight) return;
    if (isCheatDay(selectedDayKey)) return;
    _updateMealTotals();
    final total = _mealTotals.values.fold(0.0, (s, e) => s + e['calories']!);
    final g = goalCalories;
    if (g <= 0) return;
    final prefs = await SharedPreferences.getInstance();
    if (total <= g) {
      if (prefs.getString(_kSurplusCheatPromptDayKey) == selectedDayKey) {
        await prefs.remove(_kSurplusCheatPromptDayKey);
      }
      return;
    }
    if (prefs.getString(_kSurplusCheatPromptDayKey) == selectedDayKey) {
      return;
    }
    if (!mounted) return;
    _dailyOverDialogInFlight = true;
    try {
      final surplus = total - g;
      final eaten = total.toStringAsFixed(0);
      final goalS = g.toStringAsFixed(0);
      final overS = surplus.toStringAsFixed(0);
      final stepsEst = _walkStepsEstimateForKcal(surplus, currentWeightKg);
      final curE = _effectiveCutExtraStepsTotal(selectedDayKey);
      final solE =
          _suggestedExtraStepsToCoverInSol(curE, surplus, currentWeightKg);
      final kDelta = kcalFromExtraCutSteps(solE, currentWeightKg) -
          kcalFromExtraCutSteps(curE, currentWeightKg);
      if (!mounted) return;
      final choice = await showDialog<String>(
        context: context,
        builder: (ctx) => AlertDialog(
          backgroundColor: const Color(0xFF1E1E1E),
          title: Text(t("daily_over_title")),
          content: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Text(
                  tFmt("daily_over_body", {
                    "eaten": eaten,
                    "goal": goalS,
                    "over": overS,
                  }),
                  style: const TextStyle(height: 1.4),
                ),
                const SizedBox(height: 12),
                Text(
                  tFmt("daily_over_steps_est", {
                    "steps": stepsEst.toString(),
                    "kcal": surplus.toStringAsFixed(0),
                  }),
                  style: const TextStyle(height: 1.4, color: Colors.white70),
                ),
                if (nutritionMode == "Diät") ...[
                  const SizedBox(height: 10),
                  FilledButton.tonal(
                    onPressed: () => Navigator.pop(ctx, "steps"),
                    child: Text(t("daily_over_apply_steps")),
                  ),
                  const SizedBox(height: 8),
                ],
                FilledButton(
                  onPressed: () => Navigator.pop(ctx, "cheat"),
                  child: Text(t("daily_over_cheat")),
                ),
                const SizedBox(height: 6),
                TextButton(
                  onPressed: () => Navigator.pop(ctx, "ignore"),
                  child: Text(
                    t("daily_over_ignore"),
                    style: const TextStyle(color: Color(0xFFE57373)),
                  ),
                ),
                const SizedBox(height: 4),
                TextButton(
                  onPressed: () => Navigator.pop(ctx, "later"),
                  child: Text(
                    t("surplus_later"),
                    style: const TextStyle(color: Colors.white60),
                  ),
                ),
              ],
            ),
          ),
        ),
      );
      if (!mounted) return;
      if (choice == "steps") {
        if (nutritionMode == "Diät") {
          setState(() {
            final total = solE.clamp(3000, 20000);
            final base = total.clamp(3000, 10000);
            final extra = (total - base).clamp(0, 10000);
            if (base == cutExtraStepsBaseline) {
              cutExtraStepsByDay.remove(selectedDayKey);
            } else {
              cutExtraStepsByDay[selectedDayKey] = base;
            }
            if (extra <= 0) {
              cutExtraStepsAdditionalByDay.remove(selectedDayKey);
            } else {
              cutExtraStepsAdditionalByDay[selectedDayKey] = extra;
            }
            _applyAutoNutritionTargets();
          });
          _saveAppState();
          if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(
                content: Text(
                  tFmt("daily_over_snack_steps", {
                    "k": kDelta.toStringAsFixed(0),
                  }),
                ),
              ),
            );
          }
        } else {
          if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(content: Text(t("daily_over_steps_no_diet"))),
            );
          }
        }
        await prefs.setString(_kSurplusCheatPromptDayKey, selectedDayKey);
      } else if (choice == "cheat") {
        await prefs.setString(_kSurplusCheatPromptDayKey, selectedDayKey);
        if (mounted) unawaited(_openCheatDayManager(selectedDayKey));
      } else if (choice == "ignore") {
        if (!mounted) return;
        await showDialog<void>(
          context: context,
          builder: (c2) => AlertDialog(
            backgroundColor: const Color(0xFF1E1E1E),
            title: Text(t("daily_over_ignore")),
            content: Text(
              t("daily_over_ignore_body"),
              style: const TextStyle(height: 1.4),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(c2),
                child: Text(t("dialog_got_it")),
              ),
            ],
          ),
        );
        if (!mounted) return;
        await prefs.setString(_kSurplusCheatPromptDayKey, selectedDayKey);
      } else {
        await prefs.setString(_kSurplusCheatPromptDayKey, selectedDayKey);
      }
    } finally {
      _dailyOverDialogInFlight = false;
    }
  }

  Future<void> _maybeAutoOpenWeightMorning({int stackWait = 0}) async {
    if (!mounted) return;
    if (!autoOpenWeightMorning) return;
    final now = DateTime.now();
    final h = now.hour;
    if (h < 5 || h >= 12) return;

    final todayKey = dateKeyFromDate(now);
    if (weightHistory.containsKey(todayKey)) return;
    if (_lastAutoWeightPromptDay == todayKey) return;

    if (Navigator.of(context, rootNavigator: true).canPop()) {
      if (stackWait < 10) {
        await Future<void>.delayed(const Duration(milliseconds: 1400));
        if (mounted) await _maybeAutoOpenWeightMorning(stackWait: stackWait + 1);
      }
      return;
    }

    setState(() {
      _lastAutoWeightPromptDay = todayKey;
    });
    await _saveAppState();
    if (!mounted) return;
    await _openWeightDialog(forDayKey: todayKey);
  }

  String _weightKpiLine(_WeightDayEntry e) {
    final kg = e.kg.toStringAsFixed(1);
    if (e.recordedAt == null) {
      return "$kg kg";
    }
    final ti = e.recordedAt!;
    final hm =
        "${ti.hour.toString().padLeft(2, '0')}:${ti.minute.toString().padLeft(2, '0')}";
    return tFmt("weight_kpi_with_time", {"k": kg, "t": hm});
  }

  DateTime _dateTimeFromDayKeyAndTime(String dayKey, TimeOfDay tod) {
    final d = dateFromKey(dayKey);
    return DateTime(d.year, d.month, d.day, tod.hour, tod.minute);
  }

  bool _weightFormImageAvailable({String? path, String? b64}) {
    if (b64 != null && b64.isNotEmpty) return true;
    if (kIsWeb) return false;
    return path != null && path.isNotEmpty && File(path).existsSync();
  }

  Widget _weightFormImageContent({
    String? path,
    String? b64,
    BoxFit fit = BoxFit.contain,
  }) {
    if (b64 != null && b64.isNotEmpty) {
      try {
        return Image.memory(
          base64Decode(b64),
          fit: fit,
          errorBuilder: (_, __, ___) =>
              const Icon(Icons.broken_image, color: Colors.white38),
        );
      } catch (_) {}
    }
    if (!kIsWeb && path != null && path.isNotEmpty) {
      final f = File(path);
      if (f.existsSync()) {
        return Image.file(
          f,
          fit: fit,
          errorBuilder: (_, __, ___) =>
              const Icon(Icons.broken_image, color: Colors.white38),
        );
      }
    }
    return const SizedBox.shrink();
  }

  Widget _weightFormImagePreview({
    String? path,
    String? b64,
    double maxHeight = 200,
    VoidCallback? onTap,
  }) {
    if (!_weightFormImageAvailable(path: path, b64: b64)) {
      return const SizedBox.shrink();
    }
    final img = ClipRRect(
      borderRadius: BorderRadius.circular(8),
      child: ColoredBox(
        color: Colors.black26,
        child: ConstrainedBox(
          constraints: BoxConstraints(
            maxHeight: maxHeight,
            minWidth: double.infinity,
          ),
          child: _weightFormImageContent(path: path, b64: b64),
        ),
      ),
    );
    final wrapped = onTap == null
        ? img
        : GestureDetector(onTap: onTap, child: img);
    return Padding(
      padding: const EdgeInsets.only(top: 8),
      child: wrapped,
    );
  }

  void _showWeightFormImageFullscreen({String? path, String? b64}) {
    if (!_weightFormImageAvailable(path: path, b64: b64)) return;
    showDialog<void>(
      context: context,
      builder: (ctx) => Dialog(
        backgroundColor: context.sol.dailyCard,
        insetPadding: const EdgeInsets.all(16),
        child: Stack(
          children: [
            InteractiveViewer(
              minScale: 0.5,
              maxScale: 4,
              child: Padding(
                padding: const EdgeInsets.all(12),
                child: _weightFormImageContent(path: path, b64: b64),
              ),
            ),
            Positioned(
              top: 4,
              right: 4,
              child: IconButton(
                icon: const Icon(Icons.close),
                onPressed: () => Navigator.pop(ctx),
              ),
            ),
          ],
        ),
      ),
    );
  }

  bool _weightDialogOpen = false;

  Future<void> _openWeightDialog({String? forDayKey}) async {
    // Nie zwei Gewichts-Fenster übereinander (Morgen-Abfrage + Start-Hinweis).
    if (_weightDialogOpen) return;
    _weightDialogOpen = true;
    try {
      await _openWeightDialogImpl(forDayKey: forDayKey);
    } finally {
      _weightDialogOpen = false;
    }
  }

  Future<void> _openWeightDialogImpl({String? forDayKey}) async {
    final String dayKey;
    if (forDayKey != null) {
      dayKey = forDayKey;
      if (selectedDayKey != forDayKey) {
        setState(() => selectedDayKey = forDayKey);
      }
    } else {
      dayKey = selectedDayKey;
    }
    final existing = weightHistory[dayKey];
    final ctrl = TextEditingController(
      text: existing != null ? existing.kg.toStringAsFixed(1) : "",
    );
    final dayD = dateFromKey(dayKey);
    final now = DateTime.now();
    var tod = TimeOfDay.fromDateTime(
      existing?.recordedAt ??
          DateTime(dayD.year, dayD.month, dayD.day, now.hour, now.minute),
    );
    String? imagePath = existing?.formImagePath;
    String? imageB64 = existing?.formImageB64;

    Future<void> pickFormImage(ImageSource source, void Function(void Function()) setL) async {
      final x = await ImagePicker().pickImage(
        source: source,
        imageQuality: 85,
      );
      if (x == null) return;
      try {
        final bytes = await x.readAsBytes();
        if (kIsWeb) {
          setL(() {
            imageB64 = base64Encode(bytes);
            imagePath = null;
          });
        } else {
          final dir = await getApplicationDocumentsDirectory();
          final sub = p.join(dir.path, 'weight_form');
          await Directory(sub).create(recursive: true);
          final dest = p.join(sub, '$dayKey.jpg');
          await File(dest).writeAsBytes(bytes);
          setL(() {
            imagePath = dest;
            imageB64 = base64Encode(bytes);
          });
        }
      } catch (_) {}
    }

    await showDialog<void>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setL) => AlertDialog(
          title: Text("${t("enter_weight")} ($dayKey)"),
          content: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                TextField(
                  controller: ctrl,
                  keyboardType:
                      const TextInputType.numberWithOptions(decimal: true),
                  decoration: _touchInputDecoration("kg"),
                ),
                const SizedBox(height: 10),
                OutlinedButton.icon(
                  onPressed: () async {
                    final picked = await showTimePicker(
                      context: ctx,
                      initialTime: tod,
                    );
                    if (picked != null) {
                      setL(() => tod = picked);
                    }
                  },
                  icon: const Icon(Icons.schedule, size: 20),
                  label: Text(
                    "${t("weight_time_label")}: ${tod.hour.toString().padLeft(2, '0')}:${tod.minute.toString().padLeft(2, '0')}",
                  ),
                ),
                const SizedBox(height: 8),
                Row(
                  children: [
                    Expanded(
                      child: OutlinedButton.icon(
                        onPressed: () => pickFormImage(ImageSource.gallery, setL),
                        icon: const Icon(Icons.photo_library_outlined, size: 20),
                        label: Text(t("weight_form_pick_gallery")),
                      ),
                    ),
                    const SizedBox(width: 8),
                    Expanded(
                      child: OutlinedButton.icon(
                        onPressed: () => pickFormImage(ImageSource.camera, setL),
                        icon: const Icon(Icons.photo_camera_outlined, size: 20),
                        label: Text(t("weight_form_pick_camera")),
                      ),
                    ),
                  ],
                ),
                Padding(
                  padding: const EdgeInsets.only(top: 6),
                  child: Text(
                    t("weight_form_where_hint"),
                    style: const TextStyle(
                      fontSize: 11,
                      color: Colors.white38,
                      height: 1.35,
                    ),
                  ),
                ),
                _weightFormImagePreview(
                  path: imagePath,
                  b64: imageB64,
                  maxHeight: 220,
                  onTap: () => _showWeightFormImageFullscreen(
                    path: imagePath,
                    b64: imageB64,
                  ),
                ),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: Text(t("cancel")),
            ),
            TextButton(
              onPressed: () async {
                final w = _safeDouble(ctrl.text);
                if (w == null) return;
                final at = _dateTimeFromDayKeyAndTime(dayKey, tod);
                setState(() {
                  weightHistory[dayKey] = _WeightDayEntry(
                    kg: w,
                    recordedAt: at,
                    formImagePath: kIsWeb ? null : imagePath,
                    formImageB64: kIsWeb ? imageB64 : null,
                  );
                  if (dayKey == dateKeyFromDate(DateTime.now())) {
                    currentWeightKg = w;
                    if (nutritionMode != "Advanced") {
                      _applyAutoNutritionTargets();
                    }
                  }
                });
                await _saveAppState();
                if (ctx.mounted) Navigator.pop(ctx);
              },
              child: Text(t("save")),
            ),
          ],
        ),
      ),
    );
  }

  void _showBlessing() {
    showDialog(
      context: context,
      barrierDismissible: false,
      barrierColor: Colors.black54,
      builder: (_) => _BlessingPopup(message: t("blessing")),
    );
  }

  bool _mealNoteHasVisibleLines(String dayKey, String meal) {
    final lines = mealDayNoteLists[dayKey]?[meal];
    if (lines == null || lines.isEmpty) return false;
    return lines.any((e) => e.text.trim().isNotEmpty);
  }

  bool _mealNoteHasOpenTodos(String dayKey, String meal) {
    final lines = mealDayNoteLists[dayKey]?[meal];
    if (lines == null) return false;
    return lines.any((e) => e.text.trim().isNotEmpty && !e.done);
  }
}

class _AiMealReviewDialog extends StatefulWidget {
  const _AiMealReviewDialog({
    required this.dish,
    required this.lines,
    required this.foodDatabase,
    required this.t,
    required this.tFmt,
    required this.touchInputDecoration,
    required this.trackMeal,
    required this.fillGramsForTarget,
    required this.displayValueForGrams,
  });

  final String dish;
  final List<aiphoto.AiLineRaw> lines;
  final List<Food> foodDatabase;
  final String Function(String) t;
  final String Function(String, Map<String, Object>) tFmt;
  final InputDecoration Function(String) touchInputDecoration;
  final String trackMeal;
  final double? Function(
    Food food,
    String inputMode, {
    String? preCarb,
  }) fillGramsForTarget;
  final double? Function(Food food, String inputMode, double grams)
      displayValueForGrams;

  @override
  State<_AiMealReviewDialog> createState() => _AiMealReviewDialogState();
}

class _AiMealReviewDialogState extends State<_AiMealReviewDialog> {
  late List<Food?> _selected;
  late List<TextEditingController> _gramCtrls;
  late List<bool> _aiMatched;
  late List<String> _inputMode;

  @override
  void initState() {
    super.initState();
    _selected = [];
    _aiMatched = [];
    _gramCtrls = [];
    _inputMode = [];
    for (final it in widget.lines) {
      final m = aiphoto.matchFoodByAiName(
        widget.foodDatabase,
        it.catalogName,
        (x) => x.name,
      );
      _selected.add(m ?? widget.foodDatabase.first);
      _aiMatched.add(m != null);
      _gramCtrls.add(
        TextEditingController(text: it.grams.toStringAsFixed(0)),
      );
      _inputMode.add("grams");
    }
  }

  @override
  void dispose() {
    for (final c in _gramCtrls) {
      c.dispose();
    }
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final foods = List<Food>.from(widget.foodDatabase)
      ..sort((a, b) => a.name.toLowerCase().compareTo(b.name.toLowerCase()));
    return AlertDialog(
      title: Text(widget.t("ai_review_title")),
      content: _solConstrainedDialogScrollBody(
        context,
        Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          mainAxisSize: MainAxisSize.min,
          children: [
            if (widget.dish.isNotEmpty) ...[
              Text(
                widget.dish,
                style: const TextStyle(
                  color: Color(0xFFC9A24A),
                  fontSize: 13.5,
                  height: 1.35,
                ),
              ),
              const SizedBox(height: 12),
            ],
            for (var i = 0; i < widget.lines.length; i++) ...[
              if (!_aiMatched[i])
                Padding(
                  padding: const EdgeInsets.only(bottom: 4),
                  child: Text(
                    widget.tFmt("ai_unmatched_line", {
                      "n": widget.lines[i].catalogName,
                    }),
                    style: const TextStyle(
                      color: Color(0xFFFFB74D),
                      fontSize: 11,
                    ),
                  ),
                ),
              Padding(
                padding: const EdgeInsets.only(bottom: 10),
                child: Builder(
                  builder: (context) {
                    final f = _selected[i]!;
                    void applyRowFill(String mode, {String? preCarb}) {
                      final gFill = widget.fillGramsForTarget(
                        f,
                        mode,
                        preCarb: preCarb,
                      );
                      if (gFill == null || gFill <= 0) {
                        ScaffoldMessenger.of(context).showSnackBar(
                          SnackBar(
                            content: Text(widget.t("track_fill_none")),
                          ),
                        );
                        return;
                      }
                      setState(() {
                        _inputMode[i] = mode;
                        final d = widget.displayValueForGrams(f, mode, gFill);
                        _gramCtrls[i].text = (d ?? gFill).round().toString();
                      });
                    }

                    return Column(
                      crossAxisAlignment: CrossAxisAlignment.stretch,
                      children: [
                        Row(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Expanded(
                              child: DropdownButtonFormField<Food>(
                                isExpanded: true,
                                value: f,
                                decoration: widget.touchInputDecoration(
                                  widget.t("choose_food"),
                                ),
                                dropdownColor: const Color(0xFF1F1F1F),
                                items: foods
                                    .map(
                                      (ff) => DropdownMenuItem(
                                        value: ff,
                                        child: Text(
                                          ff.name,
                                          style: const TextStyle(fontSize: 14),
                                          overflow: TextOverflow.ellipsis,
                                        ),
                                      ),
                                    )
                                    .toList(),
                                onChanged: (v) {
                                  if (v == null) return;
                                  setState(() => _selected[i] = v);
                                },
                              ),
                            ),
                            const SizedBox(width: 6),
                            SizedBox(
                              width: 100,
                              child: DropdownButtonFormField<String>(
                                isExpanded: true,
                                value: _inputMode[i],
                                decoration: widget.touchInputDecoration(""),
                                items: [
                                  DropdownMenuItem(
                                    value: "grams",
                                    child: Text(
                                      widget.t("track_mode_grams"),
                                      style: const TextStyle(fontSize: 12),
                                    ),
                                  ),
                                  if (f.calories > 0.01)
                                    DropdownMenuItem(
                                      value: "kcal",
                                      child: Text(
                                        widget.t("track_mode_kcal"),
                                        style: const TextStyle(fontSize: 12),
                                      ),
                                    ),
                                  if (f.protein > 0.01)
                                    DropdownMenuItem(
                                      value: "protein",
                                      child: Text(
                                        widget.t("track_mode_protein"),
                                        style: const TextStyle(fontSize: 12),
                                      ),
                                    ),
                                  if (f.carbs > 0.01)
                                    DropdownMenuItem(
                                      value: "carbs",
                                      child: Text(
                                        widget.t("track_mode_carbs"),
                                        style: const TextStyle(fontSize: 12),
                                      ),
                                    ),
                                  if (f.fat > 0.01)
                                    DropdownMenuItem(
                                      value: "fat",
                                      child: Text(
                                        widget.t("track_mode_fat"),
                                        style: const TextStyle(fontSize: 12),
                                      ),
                                    ),
                                ],
                                onChanged: (v) {
                                  if (v == null) return;
                                  setState(() => _inputMode[i] = v);
                                },
                              ),
                            ),
                          ],
                        ),
                        const SizedBox(height: 4),
                        TextField(
                          controller: _gramCtrls[i],
                          onChanged: (_) => setState(() {}),
                          keyboardType: const TextInputType.numberWithOptions(
                            decimal: true,
                          ),
                          decoration: widget.touchInputDecoration(
                            widget.t("track_value_label"),
                          ),
                        ),
                        const SizedBox(height: 4),
                        Align(
                          alignment: Alignment.centerLeft,
                          child: Text(
                            widget.t("track_fill_group_label"),
                            style: const TextStyle(
                              fontSize: 10.5,
                              color: Color(0xFFFFB74D),
                              fontWeight: FontWeight.w600,
                            ),
                          ),
                        ),
                        const SizedBox(height: 2),
                        Wrap(
                          spacing: 4,
                          runSpacing: 2,
                          children: [
                            if (f.protein > 0.01)
                              ActionChip(
                                label: Text(
                                  widget.t("track_fill_protein"),
                                  style: const TextStyle(fontSize: 10.5),
                                ),
                                onPressed: () => applyRowFill("protein"),
                              ),
                            if (f.carbs > 0.01 &&
                                widget.trackMeal != "Pre-Workout")
                              ActionChip(
                                label: Text(
                                  widget.t("track_fill_carbs"),
                                  style: const TextStyle(fontSize: 10.5),
                                ),
                                onPressed: () => applyRowFill("carbs"),
                              ),
                            if (widget.trackMeal == "Pre-Workout" &&
                                f.carbs > 0.01) ...[
                              ActionChip(
                                label: Text(
                                  widget.t("track_fill_carb_complex"),
                                  style: const TextStyle(fontSize: 10.5),
                                ),
                                onPressed: () => applyRowFill("carbs",
                                    preCarb: "komplex"),
                              ),
                              ActionChip(
                                label: Text(
                                  widget.t("track_fill_carb_simple"),
                                  style: const TextStyle(fontSize: 10.5),
                                ),
                                onPressed: () => applyRowFill("carbs",
                                    preCarb: "einfach"),
                              ),
                            ],
                            if (f.fat > 0.01)
                              ActionChip(
                                label: Text(
                                  widget.t("track_fill_fat"),
                                  style: const TextStyle(fontSize: 10.5),
                                ),
                                onPressed: () => applyRowFill("fat"),
                              ),
                            if (f.calories > 0.01)
                              ActionChip(
                                label: Text(
                                  widget.t("track_fill_kcal"),
                                  style: const TextStyle(fontSize: 10.5),
                                ),
                                onPressed: () => applyRowFill("kcal"),
                              ),
                          ],
                        ),
                      ],
                    );
                  },
                ),
              ),
            ],
          ],
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(context, null),
          child: Text(widget.t("cancel")),
        ),
        FilledButton(
          onPressed: () {
            final out = <({Food food, double grams})>[];
            for (var i = 0; i < _selected.length; i++) {
              final f = _selected[i];
              if (f == null) continue;
              final mode = _inputMode[i];
              final raw = _gramCtrls[i].text.trim().replaceAll(",", ".");
              final v = raw.isEmpty ? null : double.tryParse(raw);
              if (v == null || v <= 0) {
                ScaffoldMessenger.of(context).showSnackBar(
                  SnackBar(content: Text(widget.t("track_error_bad"))),
                );
                return;
              }
              final gOut = foodGramsFromTrackInput(f, mode, v);
              if (gOut == null || gOut <= 0) {
                ScaffoldMessenger.of(context).showSnackBar(
                  SnackBar(content: Text(widget.t("track_error_bad"))),
                );
                return;
              }
              out.add((food: f, grams: gOut));
            }
            if (out.isEmpty) return;
            Navigator.pop(context, out);
          },
          child: Text(widget.t("ai_add_all")),
        ),
      ],
    );
  }
}

class _MealNoteChecklistDialog extends StatefulWidget {
  const _MealNoteChecklistDialog({
    required this.dayKey,
    required this.mealLabel,
    required this.initial,
    required this.t,
  });

  final String dayKey;
  final String mealLabel;
  final List<MealNoteLine> initial;
  final String Function(String) t;

  @override
  State<_MealNoteChecklistDialog> createState() =>
      _MealNoteChecklistDialogState();
}

class _MealNoteChecklistDialogState extends State<_MealNoteChecklistDialog> {
  late List<MealNoteLine> _rows;
  late List<TextEditingController> _ctls;

  @override
  void initState() {
    super.initState();
    _rows = List<MealNoteLine>.from(widget.initial);
    if (_rows.isEmpty) {
      _rows = [const MealNoteLine()];
    }
    _ctls = _rows.map((e) => TextEditingController(text: e.text)).toList();
  }

  @override
  void dispose() {
    for (final c in _ctls) {
      c.dispose();
    }
    super.dispose();
  }

  void _syncTextFromFields() {
    for (var i = 0; i < _rows.length; i++) {
      _rows[i] = _rows[i].copyWith(text: _ctls[i].text);
    }
  }

  void _addLine() {
    setState(() {
      _rows.add(const MealNoteLine());
      _ctls.add(TextEditingController());
    });
  }

  void _removeAt(int i) {
    if (_rows.length <= 1) {
      setState(() {
        _rows[0] = const MealNoteLine();
        _ctls[0].clear();
      });
      return;
    }
    setState(() {
      _ctls[i].dispose();
      _ctls.removeAt(i);
      _rows.removeAt(i);
    });
  }

  List<MealNoteLine> _buildResult() {
    _syncTextFromFields();
    return _rows
        .map((e) => e.copyWith(text: e.text.trim()))
        .where((e) => e.text.isNotEmpty)
        .toList();
  }

  @override
  Widget build(BuildContext context) {
    final t = widget.t;
    return AlertDialog(
      title: Text("${t("meal_note")} — ${widget.mealLabel}"),
      content: SizedBox(
        width: double.maxFinite,
        child: SingleChildScrollView(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Text(
                widget.dayKey,
                style: const TextStyle(
                  fontSize: 12.5,
                  color: Colors.white60,
                ),
              ),
              const SizedBox(height: 8),
              Text(
                t("meal_note_checklist_sub"),
                style: const TextStyle(
                  fontSize: 12,
                  color: Colors.white60,
                  height: 1.35,
                ),
              ),
              const SizedBox(height: 10),
              ...List.generate(_rows.length, (i) => _rowWidget(i, t)),
              const SizedBox(height: 2),
              Align(
                alignment: Alignment.centerLeft,
                child: TextButton.icon(
                  onPressed: _addLine,
                  icon: const Icon(Icons.add, size: 20),
                  label: Text(t("meal_note_add_line")),
                ),
              ),
            ],
          ),
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(context),
          child: Text(t("cancel")),
        ),
        TextButton(
          onPressed: () => Navigator.pop(context, _buildResult()),
          child: Text(t("save")),
        ),
      ],
    );
  }

  Widget _rowWidget(int i, String Function(String) t) {
    final r = _rows[i];
    final canToggle = _ctls[i].text.trim().isNotEmpty;
    return Padding(
      padding: const EdgeInsets.only(bottom: 6),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Padding(
            padding: const EdgeInsets.only(top: 0),
            child: SizedBox(
              width: 40,
              height: 40,
              child: Checkbox(
                value: r.done,
                onChanged: canToggle
                    ? (v) {
                        setState(() {
                          _syncTextFromFields();
                          _rows[i] =
                              _rows[i].copyWith(done: v ?? false);
                        });
                      }
                    : null,
              ),
            ),
          ),
          Expanded(
            child: r.done
                ? Padding(
                    padding: const EdgeInsets.only(top: 10, left: 2),
                    child: Text(
                      _ctls[i].text.trim().isEmpty
                          ? "…"
                          : _ctls[i].text,
                      maxLines: 4,
                      style: const TextStyle(
                        color: Colors.white70,
                        decoration: TextDecoration.lineThrough,
                        decorationColor: Colors.white60,
                        height: 1.25,
                      ),
                    ),
                  )
                : TextField(
                    controller: _ctls[i],
                    onChanged: (_) => setState(() {}),
                    maxLines: 3,
                    minLines: 1,
                    style: const TextStyle(fontSize: 15),
                    decoration: InputDecoration(
                      isDense: true,
                      hintText: t("meal_note_line_hint"),
                      border: const OutlineInputBorder(),
                      contentPadding: const EdgeInsets.symmetric(
                        horizontal: 10,
                        vertical: 10,
                      ),
                    ),
                  ),
          ),
          IconButton(
            padding: const EdgeInsets.only(top: 2),
            constraints: const BoxConstraints(minWidth: 32, minHeight: 32),
            icon: const Icon(Icons.close, size: 20, color: Colors.white60),
            onPressed: () => _removeAt(i),
            tooltip: t("meal_note_remove_line"),
          ),
        ],
      ),
    );
  }
}

const String _kBarcodeManualEntry = "__manual__";

class _BarcodeScanDialog extends StatefulWidget {
  const _BarcodeScanDialog({required this.t});
  final String Function(String) t;
  @override
  State<_BarcodeScanDialog> createState() => _BarcodeScanDialogState();
}

class _BarcodeScanDialogState extends State<_BarcodeScanDialog> {
  final MobileScannerController _controller = MobileScannerController();
  bool _closed = false;
  bool _busy = false;
  String? _msg;

  void _finish(String v) {
    if (_closed) return;
    _closed = true;
    if (mounted) Navigator.of(context).pop<String>(v);
  }

  /// Web-App: Foto machen und Barcode daraus lesen (zuverlässiger als Live-Bild auf dem iPhone).
  Future<void> _scanFromPhoto() async {
    if (_busy) return;
    setState(() {
      _busy = true;
      _msg = null;
    });
    try {
      if (!kIsWeb) {
        try {
          await _controller.stop();
        } catch (_) {}
      }
      final x = await ImagePicker().pickImage(
        source: ImageSource.camera,
        maxWidth: 2400,
        imageQuality: 92,
      );
      if (x == null) {
        if (mounted) setState(() => _busy = false);
        if (!kIsWeb) {
          try {
            await _controller.start();
          } catch (_) {}
        }
        return;
      }
      final bytes = await x.readAsBytes();
      final code = await decodeBarcodeFromPhoto(bytes, x.mimeType ?? "image/jpeg");
      final digits = (code ?? "").replaceAll(RegExp(r'[^\d]'), "");
      if (digits.length >= 8) {
        _finish(code!);
        return;
      }
      // Nicht lesbar: direkt „neues Lebensmittel“ zum selbst Eintragen.
      _finish(_kBarcodeManualEntry);
      return;
      // ignore: dead_code
      if (mounted) {
        setState(() {
          _busy = false;
          _msg = barcodeLibLoaded()
              ? widget.t("barcode_photo_fail")
              : widget.t("barcode_lib_fail");
        });
      }
      if (!kIsWeb) {
        try {
          await _controller.start();
        } catch (_) {}
      }
    } catch (_) {
      if (mounted) {
        setState(() {
          _busy = false;
          _msg = widget.t("barcode_photo_fail");
        });
      }
    }
  }

  Future<void> _enterManually() async {
    final ctrl = TextEditingController();
    final v = await showDialog<String>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text(widget.t("barcode_manual_title")),
        content: TextField(
          controller: ctrl,
          autofocus: true,
          keyboardType: TextInputType.number,
          decoration: InputDecoration(hintText: widget.t("barcode_manual_hint")),
          onSubmitted: (t) => Navigator.pop(ctx, t),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx),
            child: Text(widget.t("cancel")),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(ctx, ctrl.text),
            child: Text(widget.t("barcode_manual_ok")),
          ),
        ],
      ),
    );
    final digits = (v ?? "").replaceAll(RegExp(r'[^\d]'), "");
    if (digits.length >= 8) {
      _finish(digits);
    } else if (v != null && mounted) {
      setState(() => _msg = widget.t("db_barcode_short"));
    }
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AlertDialog(
      title: Text(widget.t("db_barcode_add")),
      content: SizedBox(
        width: 320,
        height: 320,
        child: ClipRRect(
          borderRadius: BorderRadius.circular(8),
          child: Stack(
            children: [
              if (kIsWeb)
                // Web-App: Live-Kamera erkennt auf dem iPhone nicht zuverlässig
                // (zeigte nur „!“). Stattdessen direkt Foto scannen.
                Positioned.fill(
                  child: ColoredBox(
                    color: Colors.black,
                    child: Padding(
                      padding: const EdgeInsets.all(20),
                      child: Column(
                        mainAxisAlignment: MainAxisAlignment.center,
                        children: [
                          const Icon(Icons.qr_code_scanner,
                              size: 56, color: Color(0xFFC9A24A)),
                          const SizedBox(height: 14),
                          Text(
                            widget.t("barcode_web_hint"),
                            textAlign: TextAlign.center,
                            style: const TextStyle(
                                color: Colors.white70, fontSize: 13.5, height: 1.4),
                          ),
                        ],
                      ),
                    ),
                  ),
                )
              else
              MobileScanner(
                controller: _controller,
                onDetect: (cap) {
                  if (_closed) return;
                  for (final b in cap.barcodes) {
                    final v = b.rawValue;
                    if (v == null || v.isEmpty) continue;
                    if (v.replaceAll(RegExp(r'[^\d]'), "").length < 8) {
                      continue;
                    }
                    _finish(v);
                    return;
                  }
                },
              ),
              Positioned(
                right: 4,
                top: 4,
                child: Material(
                  color: Colors.black45,
                  borderRadius: BorderRadius.circular(20),
                  child: IconButton(
                    icon: const Icon(Icons.close, color: Colors.white),
                    onPressed: () {
                      if (_closed) return;
                      _closed = true;
                      Navigator.of(context).pop();
                    },
                  ),
                ),
              ),
              if (_busy)
                const Positioned.fill(
                  child: ColoredBox(
                    color: Colors.black54,
                    child: Center(child: CircularProgressIndicator()),
                  ),
                ),
            ],
          ),
        ),
      ),
      actionsAlignment: MainAxisAlignment.spaceBetween,
      actions: [
        if (_msg != null)
          SizedBox(
            width: double.infinity,
            child: Text(
              _msg!,
              style: const TextStyle(color: Color(0xFFFFB74D), fontSize: 12.5),
            ),
          ),
        TextButton(
          onPressed: _busy ? null : _enterManually,
          child: Text(widget.t("barcode_manual_button")),
        ),
        if (kIsWeb)
          FilledButton.icon(
            onPressed: _busy ? null : _scanFromPhoto,
            icon: const Icon(Icons.photo_camera, size: 18),
            label: Text(widget.t("barcode_photo_button")),
          ),
      ],
    );
  }
}

class _WeekStartCalendarPicker extends StatefulWidget {
  const _WeekStartCalendarPicker({
    required this.weekStartWeekday,
    required this.initialDate,
    required this.weekdayShort,
    required this.legendText,
    required this.onDayPicked,
  });

  final int weekStartWeekday;
  final DateTime initialDate;
  final String Function(int) weekdayShort;
  final String legendText;
  final void Function(DateTime) onDayPicked;

  @override
  State<_WeekStartCalendarPicker> createState() =>
      _WeekStartCalendarPickerState();
}

class _WeekStartCalendarPickerState extends State<_WeekStartCalendarPicker> {
  late DateTime _visibleMonth;
  late DateTime _selected;

  static DateTime _only(DateTime d) => DateTime(d.year, d.month, d.day);

  @override
  void initState() {
    super.initState();
    final i = widget.initialDate;
    _visibleMonth = DateTime(i.year, i.month, 1);
    _selected = _only(i);
  }

  static bool _sameDay(DateTime a, DateTime b) =>
      a.year == b.year && a.month == b.month && a.day == b.day;

  int _daysInMonth(int y, int m) => DateTime(y, m + 1, 0).day;

  void _onCellTap(DateTime d) {
    if (d.isBefore(DateTime(2020, 1, 1)) || d.isAfter(DateTime(2100, 12, 31))) {
      return;
    }
    final od = _only(d);
    setState(() => _selected = od);
    widget.onDayPicked(od);
  }

  @override
  Widget build(BuildContext context) {
    final y = _visibleMonth.year;
    final m = _visibleMonth.month;
    final first = DateTime(y, m, 1);
    final dim = _daysInMonth(y, m);
    final lead = first.weekday - 1;
    final totalCells = ((lead + dim + 6) ~/ 7) * 7;
    final loc = MaterialLocalizations.of(context);
    final monthYear = loc.formatMonthYear(_visibleMonth);
    final today = _only(DateTime.now());

    return SizedBox(
      width: 340,
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              IconButton(
                icon: const Icon(Icons.chevron_left),
                onPressed: () {
                  setState(() {
                    _visibleMonth = DateTime(y, m - 1, 1);
                    if (_visibleMonth.isBefore(DateTime(2020, 1, 1))) {
                      _visibleMonth = DateTime(2020, 1, 1);
                    }
                  });
                },
              ),
              Text(
                monthYear,
                style: const TextStyle(
                  fontWeight: FontWeight.w700,
                  fontSize: 15,
                ),
              ),
              IconButton(
                icon: const Icon(Icons.chevron_right),
                onPressed: () {
                  setState(() {
                    _visibleMonth = DateTime(y, m + 1, 1);
                    if (_visibleMonth.isAfter(DateTime(2100, 12, 1))) {
                      _visibleMonth = DateTime(2100, 12, 1);
                    }
                  });
                },
              ),
            ],
          ),
          const SizedBox(height: 4),
          Row(
            children: List.generate(7, (i) {
              final wd = i + 1;
              return Expanded(
                child: Center(
                  child: Text(
                    widget.weekdayShort(wd),
                    style: const TextStyle(
                      fontSize: 11,
                      color: Colors.white60,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                ),
              );
            }),
          ),
          const SizedBox(height: 2),
          GridView.builder(
            shrinkWrap: true,
            physics: const NeverScrollableScrollPhysics(),
            gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
              crossAxisCount: 7,
              mainAxisSpacing: 2,
              crossAxisSpacing: 2,
              mainAxisExtent: 36,
            ),
            itemCount: totalCells,
            itemBuilder: (context, i) {
              if (i < lead || i >= lead + dim) {
                return const SizedBox.shrink();
              }
              final day = i - lead + 1;
              final d = DateTime(y, m, day);
              final isWStart = d.weekday == widget.weekStartWeekday;
              final isSel = _sameDay(d, _selected);
              final isToday = _sameDay(d, today);
              return Material(
                color: Colors.transparent,
                child: InkWell(
                  onTap: () => _onCellTap(d),
                  borderRadius: BorderRadius.circular(8),
                  child: DecoratedBox(
                    decoration: BoxDecoration(
                      borderRadius: BorderRadius.circular(8),
                      color: isWStart
                          ? const Color(0x40C9A24A)
                          : Colors.transparent,
                      border: Border.all(
                        color: isSel
                            ? const Color(0xFFC9A24A)
                            : (isToday
                                ? Colors.white30
                                : (isWStart
                                    ? const Color(0x99C9A24A)
                                    : Colors.transparent)),
                        width: isSel ? 2.2 : 1,
                      ),
                    ),
                    child: Center(
                      child: Text(
                        "$day",
                        style: TextStyle(
                          fontWeight: isSel ? FontWeight.w800 : FontWeight.w600,
                          fontSize: 13,
                          color: isSel
                              ? const Color(0xFFC9A24A)
                              : (isWStart
                                  ? Colors.white
                                  : Colors.white.withValues(alpha: 0.92)),
                        ),
                      ),
                    ),
                  ),
                ),
              );
            },
          ),
          const SizedBox(height: 8),
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Container(
                width: 18,
                height: 18,
                margin: const EdgeInsets.only(top: 2, right: 8),
                decoration: BoxDecoration(
                  color: const Color(0x40C9A24A),
                  borderRadius: BorderRadius.circular(4),
                  border: Border.all(
                    color: const Color(0x99C9A24A),
                    width: 1,
                  ),
                ),
              ),
              Expanded(
                child: Text(
                  widget.legendText,
                  style: const TextStyle(
                    fontSize: 11.5,
                    color: Colors.white60,
                    height: 1.35,
                  ),
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }
}

class _BlessingPopup extends StatefulWidget {
  final String message;
  const _BlessingPopup({required this.message});

  @override
  State<_BlessingPopup> createState() => _BlessingPopupState();
}

class _BlessingPopupState extends State<_BlessingPopup>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller;
  late final Animation<double> _fade;
  late final Animation<double> _scale;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      duration: const Duration(milliseconds: 2000),
      vsync: this,
    );
    _fade = TweenSequence<double>([
      TweenSequenceItem(tween: Tween(begin: 0.0, end: 1.0), weight: 22),
      TweenSequenceItem(tween: ConstantTween(1.0), weight: 56),
      TweenSequenceItem(tween: Tween(begin: 1.0, end: 0.0), weight: 22),
    ]).animate(_controller);
    _scale = TweenSequence<double>([
      TweenSequenceItem(
        tween: Tween(begin: 0.8, end: 1.04)
            .chain(CurveTween(curve: Curves.easeOutBack)),
        weight: 22,
      ),
      TweenSequenceItem(tween: ConstantTween(1.04), weight: 56),
      TweenSequenceItem(
        tween: Tween(begin: 1.04, end: 0.9)
            .chain(CurveTween(curve: Curves.easeIn)),
        weight: 22,
      ),
    ]).animate(_controller);
    _controller.forward().whenComplete(() {
      if (mounted && Navigator.canPop(context)) {
        Navigator.of(context).pop();
      }
    });
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    const goldish = Color(0xFFC9A24A);
    return Center(
      child: AnimatedBuilder(
        animation: _controller,
        builder: (context, child) => Opacity(
          opacity: _fade.value,
          child: Transform.scale(scale: _scale.value, child: child),
        ),
        child: Material(
          color: Colors.transparent,
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 320),
            child: Container(
              padding: const EdgeInsets.symmetric(
                  vertical: 22, horizontal: 26),
              decoration: BoxDecoration(
                color: const Color(0xFF101010),
                borderRadius: BorderRadius.circular(18),
                border: Border.all(
                  color: goldish.withValues(alpha: 0.35),
                  width: 1,
                ),
                boxShadow: [
                  BoxShadow(
                    color: goldish.withValues(alpha: 0.20),
                    blurRadius: 36,
                    spreadRadius: 2,
                  ),
                ],
              ),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  const Text("🌞", style: TextStyle(fontSize: 52)),
                  const SizedBox(height: 10),
                  Text(
                    widget.message,
                    textAlign: TextAlign.center,
                    style: const TextStyle(
                      color: Colors.white,
                      fontSize: 15,
                      fontStyle: FontStyle.italic,
                      height: 1.35,
                      letterSpacing: 0.2,
                    ),
                  ),
                ],
              ),
            ),
          ),
        ),
      ),
    );
  }
}

class _ShoppingListsEditor extends StatefulWidget {
  const _ShoppingListsEditor({
    required this.day,
    required this.month,
    required this.foods,
    required this.t,
    required this.onSaved,
  });

  final _ShoppingListBundle day;
  final _ShoppingListBundle month;
  final List<Food> foods;
  final String Function(String) t;
  final void Function(_ShoppingListBundle day, _ShoppingListBundle month)
      onSaved;

  @override
  State<_ShoppingListsEditor> createState() => _ShoppingListsEditorState();
}

class _ShoppingListsEditorState extends State<_ShoppingListsEditor> {
  late _ShoppingListBundle day;
  late _ShoppingListBundle month;
  bool isMonthTab = false;

  @override
  void initState() {
    super.initState();
    day = widget.day;
    month = widget.month;
  }

  void _persist() => widget.onSaved(day, month);

  /// Liste als Text: offene Einträge, nach Gruppe/Laden.
  String _listAsText(_ShoppingListBundle b) {
    final t = widget.t;
    final out = StringBuffer(
        "🛒 ${t("shop_title")} · ${isMonthTab ? t("shop_tab_month") : t("shop_tab_day")}\n");
    var any = false;
    for (final g in b.groups) {
      final items =
          b.entries.where((e) => e.groupId == g.id && !e.done).toList();
      if (items.isEmpty) continue;
      any = true;
      final name = g.name.trim().isEmpty ? t("shop_group_general") : g.name.trim();
      if (b.groups.length > 1) out.write("\n$name\n");
      for (final e in items) {
        final q = e.quantity.trim();
        out.write("• ${e.label.trim()}${q.isEmpty ? "" : " — $q"}\n");
      }
    }
    if (!any) out.write("\n${t("shop_empty")}\n");
    return out.toString().trimRight();
  }

  Future<void> _shareList(_ShoppingListBundle b) async {
    final text = _listAsText(b);
    // Teilen-Menü zuerst (ohne await davor), sonst blockt Safari.
    final shared = await shareText(widget.t("shop_title"), text);
    if (shared || !mounted) return;
    await Clipboard.setData(ClipboardData(text: text));
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(widget.t("shop_share_copied"))),
    );
  }

  _ShoppingListBundle get _b => isMonthTab ? month : day;

  Future<void> _moveEntryDialog(
      _ShoppingListBundle b, _ShoppingListEntry e) async {
    var gid = e.groupId;
    if (!mounted) return;
    await showDialog<void>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setL) => AlertDialog(
          title: Text(widget.t("shop_move_group")),
          content: DropdownButtonFormField<String>(
            value: gid,
            isExpanded: true,
            items: b.groups
                .map(
                  (g) => DropdownMenuItem<String>(
                    value: g.id,
                    child: Text(
                      b.resolveGroupLabel(g.id, widget.t),
                      overflow: TextOverflow.ellipsis,
                    ),
                  ),
                )
                .toList(),
            onChanged: (v) => setL(() => gid = v ?? gid),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: Text(widget.t("shop_cancel")),
            ),
            TextButton(
              onPressed: () {
                setState(() => e.groupId = gid);
                _persist();
                Navigator.pop(ctx);
              },
              child: Text(widget.t("save")),
            ),
          ],
        ),
      ),
    );
  }

  Widget _entryTile(_ShoppingListBundle b, _ShoppingListEntry e) {
    final parts = <String>[];
    if (e.quantity.isNotEmpty) parts.add(e.quantity);
    if (e.recipeSourceName != null && e.recipeSourceName!.trim().isNotEmpty) {
      parts.add("«${e.recipeSourceName}»");
    }
    final sub = parts.join(" · ");

    return Dismissible(
      key: ValueKey<String>(e.id),
      direction: DismissDirection.endToStart,
      onDismissed: (_) {
        setState(() => b.entries.removeWhere((x) => x.id == e.id));
        _persist();
      },
      background: Container(
        alignment: Alignment.centerRight,
        padding: const EdgeInsets.only(right: 18),
        color: Colors.red.withValues(alpha: 0.28),
        child: const Icon(Icons.delete_outline),
      ),
      child: CheckboxListTile(
        value: e.done,
        onChanged: (v) {
          setState(() => e.done = v ?? false);
          _persist();
        },
        title: Text(
          e.label,
          style: TextStyle(
            decoration: e.done ? TextDecoration.lineThrough : null,
            color: e.done ? Colors.white38 : Colors.white,
          ),
        ),
        subtitle: sub.isEmpty
            ? null
            : Text(sub, style: const TextStyle(fontSize: 11.5)),
        secondary: IconButton(
          tooltip: widget.t("shop_move_group"),
          icon: const Icon(Icons.drive_file_move_outline, size: 20),
          onPressed: () => _moveEntryDialog(b, e),
        ),
        controlAffinity: ListTileControlAffinity.leading,
      ),
    );
  }

  Widget _buildGroupSection(_ShoppingListBundle b, _ShoppingListGroup g) {
    final items = b.entries.where((e) => e.groupId == g.id).toList();
    return Card(
      margin: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          ListTile(
            title: Text(
              b.resolveGroupLabel(g.id, widget.t),
              style: const TextStyle(fontWeight: FontWeight.w700),
            ),
            trailing: g.id != "_def"
                ? IconButton(
                    icon:
                        const Icon(Icons.delete_outline, color: Colors.white60),
                    tooltip: widget.t("delete"),
                    onPressed: () {
                      setState(() {
                        for (final e in b.entries) {
                          if (e.groupId == g.id) e.groupId = "_def";
                        }
                        b.groups.removeWhere((x) => x.id == g.id);
                      });
                      _persist();
                    },
                  )
                : null,
          ),
          if (items.isEmpty)
            Padding(
              padding: const EdgeInsets.fromLTRB(16, 0, 16, 14),
              child: Text(
                widget.t("shop_empty"),
                style: TextStyle(
                  fontSize: 12,
                  color: Colors.white.withValues(alpha: 0.32),
                ),
              ),
            )
          else
            ...items.map((e) => _entryTile(b, e)),
        ],
      ),
    );
  }

  void _addGroupDialog() {
    final c = TextEditingController();
    showDialog<void>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text(widget.t("shop_new_group")),
        content: TextField(
          controller: c,
          autofocus: true,
          decoration: InputDecoration(
            hintText: widget.t("shop_new_group_hint"),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx),
            child: Text(widget.t("shop_cancel")),
          ),
          TextButton(
            onPressed: () {
              final n = c.text.trim();
              if (n.isEmpty) return;
              setState(() {
                _b.groups.add(_ShoppingListGroup(id: _newShoppingId(), name: n));
              });
              _persist();
              Navigator.pop(ctx);
            },
            child: Text(widget.t("save")),
          ),
        ],
      ),
    ).then((_) => c.dispose());
  }

  void _addNoteDialog() {
    final c = TextEditingController();
    var gid = _b.groups.first.id;
    showDialog<void>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setL) => AlertDialog(
          title: Text(widget.t("shop_add_note")),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              DropdownButtonFormField<String>(
                value: gid,
                isExpanded: true,
                decoration: InputDecoration(labelText: widget.t("shop_group_pick")),
                items: _b.groups
                    .map(
                      (g) => DropdownMenuItem<String>(
                        value: g.id,
                        child: Text(
                          _b.resolveGroupLabel(g.id, widget.t),
                          overflow: TextOverflow.ellipsis,
                        ),
                      ),
                    )
                    .toList(),
                onChanged: (v) => setL(() => gid = v ?? gid),
              ),
              const SizedBox(height: 12),
              TextField(
                controller: c,
                maxLines: 3,
                decoration: InputDecoration(
                  hintText: widget.t("shop_add_note_hint"),
                ),
              ),
            ],
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: Text(widget.t("shop_cancel")),
            ),
            TextButton(
              onPressed: () {
                final text = c.text.trim();
                if (text.isEmpty) return;
                setState(() {
                  _b.entries.add(
                    _ShoppingListEntry(
                      id: _newShoppingId(),
                      groupId: gid,
                      label: text,
                      isNote: true,
                    ),
                  );
                });
                _persist();
                Navigator.pop(ctx);
              },
              child: Text(widget.t("save")),
            ),
          ],
        ),
      ),
    ).then((_) => c.dispose());
  }

  Future<void> _pickFoodFromDb() async {
    var needle = "";
    final food = await showModalBottomSheet<Food>(
      context: context,
      isScrollControlled: true,
      backgroundColor: const Color(0xFF1E1E1E),
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(16)),
      ),
      builder: (ctx) {
        return StatefulBuilder(
          builder: (ctx, setL) {
            final filtered = widget.foods.where((f) {
              if (needle.trim().isEmpty) return true;
              return f.name.toLowerCase().contains(needle.trim().toLowerCase());
            }).toList();
            final h = MediaQuery.sizeOf(ctx).height * 0.72;
            return SafeArea(
              child: SizedBox(
                height: h,
                child: Column(
                  children: [
                    Padding(
                      padding: const EdgeInsets.fromLTRB(16, 12, 16, 8),
                      child: TextField(
                        decoration: InputDecoration(
                          hintText: widget.t("search_food"),
                          prefixIcon: const Icon(Icons.search),
                          border: OutlineInputBorder(
                            borderRadius: BorderRadius.circular(8),
                          ),
                        ),
                        onChanged: (v) => setL(() => needle = v),
                      ),
                    ),
                    Expanded(
                      child: ListView.builder(
                        itemCount: filtered.length,
                        itemBuilder: (_, i) {
                          final f = filtered[i];
                          return ListTile(
                            title: Text(f.name),
                            onTap: () => Navigator.pop(ctx, f),
                          );
                        },
                      ),
                    ),
                  ],
                ),
              ),
            );
          },
        );
      },
    );
    if (food == null || !mounted) return;

    var gid = _b.groups.first.id;
    final qty = TextEditingController(text: "1");
    await showDialog<void>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setL) => AlertDialog(
          title: Text(food.name),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              DropdownButtonFormField<String>(
                value: gid,
                isExpanded: true,
                decoration:
                    InputDecoration(labelText: widget.t("shop_group_pick")),
                items: _b.groups
                    .map(
                      (g) => DropdownMenuItem<String>(
                        value: g.id,
                        child: Text(
                          _b.resolveGroupLabel(g.id, widget.t),
                          overflow: TextOverflow.ellipsis,
                        ),
                      ),
                    )
                    .toList(),
                onChanged: (v) => setL(() => gid = v ?? gid),
              ),
              const SizedBox(height: 10),
              TextField(
                controller: qty,
                decoration:
                    InputDecoration(labelText: widget.t("shop_quantity")),
              ),
            ],
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: Text(widget.t("shop_cancel")),
            ),
            TextButton(
              onPressed: () {
                setState(() {
                  _b.entries.add(
                    _ShoppingListEntry(
                      id: _newShoppingId(),
                      groupId: gid,
                      label: food.name,
                      quantity: qty.text.trim(),
                      linkedFoodName: food.name,
                    ),
                  );
                });
                _persist();
                Navigator.pop(ctx);
              },
              child: Text(widget.t("shop_add_to_list")),
            ),
          ],
        ),
      ),
    );
    qty.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final t = widget.t;
    final b = _b;
    return Scaffold(
      appBar: AppBar(
        title: Text(t("shop_title")),
        actions: [
          IconButton(
            tooltip: t("shop_share"),
            icon: const Icon(Icons.ios_share),
            onPressed: () => _shareList(b),
          ),
          PopupMenuButton<String>(
            icon: const Icon(Icons.more_vert),
            onSelected: (v) {
              if (v == "clear") {
                setState(() => b.entries.removeWhere((e) => e.done));
                _persist();
              }
            },
            itemBuilder: (ctx) => [
              PopupMenuItem(
                value: "clear",
                child: Text(t("shop_clear_done")),
              ),
            ],
          ),
        ],
      ),
      body: Column(
        children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(12, 10, 12, 6),
            child: SegmentedButton<bool>(
              segments: [
                ButtonSegment<bool>(
                  value: false,
                  label: Text(t("shop_tab_day")),
                ),
                ButtonSegment<bool>(
                  value: true,
                  label: Text(t("shop_tab_month")),
                ),
              ],
              selected: {isMonthTab},
              onSelectionChanged: (s) =>
                  setState(() => isMonthTab = s.first),
            ),
          ),
          Expanded(
            child: ListView(
              padding: EdgeInsets.only(
                bottom: 20 + MediaQuery.paddingOf(context).bottom,
              ),
              children: [
                for (final g in b.groups) _buildGroupSection(b, g),
              ],
            ),
          ),
        ],
      ),
      floatingActionButton: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.end,
        children: [
          FloatingActionButton.small(
            heroTag: "shop_note",
            tooltip: t("shop_add_note"),
            onPressed: _addNoteDialog,
            child: const Icon(Icons.sticky_note_2_outlined),
          ),
          const SizedBox(height: 10),
          FloatingActionButton.small(
            heroTag: "shop_grp",
            tooltip: t("shop_new_group"),
            onPressed: _addGroupDialog,
            child: const Icon(Icons.create_new_folder_outlined),
          ),
          const SizedBox(height: 10),
          FloatingActionButton(
            heroTag: "shop_db",
            tooltip: t("shop_add_from_db"),
            onPressed: _pickFoodFromDb,
            child: const Icon(Icons.add_shopping_cart),
          ),
        ],
      ),
    );
  }
}

/// Halbrund-Ring (270°, Lücke unten) für die kcal-Übersicht.
class _KcalRingPainter extends CustomPainter {
  _KcalRingPainter({
    required this.ratio,
    required this.track,
    required this.color,
    this.outline,
  });
  final Color? outline;
  final double ratio;
  final Color track;
  final Color color;

  @override
  void paint(Canvas canvas, Size size) {
    const stroke = 11.0;
    // Quadrat aus der Breite (Box darf niedriger sein, weil unten offen).
    final d = size.width - stroke;
    final rect = Rect.fromLTWH(stroke / 2, stroke / 2, d, d);
    const start = math.pi * 0.75;
    const sweep = math.pi * 1.5;
    final base = Paint()
      ..color = track
      ..style = PaintingStyle.stroke
      ..strokeWidth = stroke
      ..strokeCap = StrokeCap.round;
    if (outline != null) {
      canvas.drawArc(
          rect,
          start,
          sweep,
          false,
          Paint()
            ..color = outline!
            ..style = PaintingStyle.stroke
            ..strokeWidth = stroke + 1.6
            ..strokeCap = StrokeCap.round);
    }
    canvas.drawArc(rect, start, sweep, false, base);
    final r = ratio.clamp(0.0, 1.0);
    if (r > 0.001) {
      final fg = Paint()
        ..color = color
        ..style = PaintingStyle.stroke
        ..strokeWidth = stroke
        ..strokeCap = StrokeCap.round;
      canvas.drawArc(rect, start, sweep * r, false, fg);
    }
  }

  @override
  bool shouldRepaint(covariant _KcalRingPainter old) =>
      old.ratio != ratio || old.color != color || old.track != track;
}


/// Skaliert ein Kind komplett (Layout + Zeichnung + Antippen), z. B. 0.86 = 86 %.
class _UniformScale extends SingleChildRenderObjectWidget {
  const _UniformScale({required this.scale, super.child});
  final double scale;

  @override
  RenderObject createRenderObject(BuildContext context) =>
      _RenderUniformScale(scale);

  @override
  void updateRenderObject(BuildContext context, _RenderUniformScale renderObject) {
    renderObject.scale = scale;
  }
}

class _RenderUniformScale extends RenderProxyBox {
  _RenderUniformScale(this._scale);
  double _scale;

  set scale(double v) {
    if (v == _scale) return;
    _scale = v;
    markNeedsLayout();
  }

  Matrix4 get _m => Matrix4.diagonal3Values(_scale, _scale, 1);

  @override
  void performLayout() {
    final c = constraints;
    final ch = child;
    if (ch == null) {
      size = c.smallest;
      return;
    }
    ch.layout(
      BoxConstraints(
        minWidth: c.minWidth / _scale,
        maxWidth: c.maxWidth / _scale,
        minHeight: c.minHeight / _scale,
        maxHeight: c.maxHeight / _scale,
      ),
      parentUsesSize: true,
    );
    size = c.constrain(ch.size * _scale);
  }

  @override
  void paint(PaintingContext context, Offset offset) {
    if (child == null) return;
    context.pushTransform(needsCompositing, offset, _m, super.paint);
  }

  @override
  bool hitTestChildren(BoxHitTestResult result, {required Offset position}) {
    final ch = child;
    if (ch == null) return false;
    return result.addWithPaintTransform(
      transform: _m,
      position: position,
      hitTest: (r, p) => ch.hitTest(r, position: p),
    );
  }

  @override
  void applyPaintTransform(RenderBox child, Matrix4 transform) {
    transform.multiply(_m);
  }
}
